insert into public.pokedex (
  id, slug, dex_no, is_default, generation, names, genera, descriptions,
  type1, type2, hp, attack, defense, special_attack, special_defense, speed, height, weight,
  growth_rate, capture_rate, hatch_counter, gender_rate, is_baby, is_legendary, is_mythical,
  evolution_chain_id, evolves_from_id, evolution, sprites
) values
  (1, 'bulbasaur', 1, true, 1,
   '{"ko":"이상해씨","en":"Bulbasaur","ja":"フシギダネ","zh-Hans":"妙蛙种子","zh-Hant":"妙蛙種子","fr":"Bulbizarre","de":"Bisasam","es":"Bulbasaur","it":"Bulbasaur"}',
   '{"ko":"씨앗포켓몬","en":"Seed Pokémon","ja":"たねポケモン","zh-Hans":"种子宝可梦","zh-Hant":"種子寶可夢","fr":"Pokémon Graine","de":"Samen-Pokémon","es":"Pokémon Semilla","it":"Pokémon Seme"}',
   '{"ko":"태어나서 얼마 동안 등의 씨앗에 담긴 영양을 섭취하며 자란다.","en":"While it is young, it uses the nutrients that are stored in the seed on its back in order to grow.","ja":"生まれて　しばらくの　あいだ背中の　タネに　つまった栄養を　とって　育つ。","zh-Hans":"在出生后的一段时间内，它会吸收背上种子里储存着的营养成长。","zh-Hant":"在出生後的一段時間內，牠會吸收背上種子裡儲存著的營養成長。","fr":"Quand il est jeune, il absorbe les nutriments conservés dans son dos pour grandir et se développer.","de":"Nach der Geburt nimmt es für eine Weile Nährstoffe über den Samen auf seinem Rücken auf.","es":"Desde que nace, crece alimentándose de los nutrientes que contiene la semilla de su lomo.","it":"Appena nato, trae nutrimento dalle sostanze contenute nel seme sul dorso."}',
   'grass', 'poison', 45, 49, 49, 65, 65, 45, 7, 69,
   'medium-slow', 45, 20, 1, false, false, false,
   1, null, null, '{"animated":"/sprites/pokemon/1.gif","animated_shiny":"/sprites/pokemon/shiny/1.gif"}'),
  (2, 'ivysaur', 2, true, 1,
   '{"ko":"이상해풀","en":"Ivysaur","ja":"フシギソウ","zh-Hans":"妙蛙草","zh-Hant":"妙蛙草","fr":"Herbizarre","de":"Bisaknosp","es":"Ivysaur","it":"Ivysaur"}',
   '{"ko":"씨앗포켓몬","en":"Seed Pokémon","ja":"たねポケモン","zh-Hans":"种子宝可梦","zh-Hant":"種子寶可夢","fr":"Pokémon Graine","de":"Samen-Pokémon","es":"Pokémon Semilla","it":"Pokémon Seme"}',
   '{"ko":"햇빛을 받을수록 몸에 힘이 솟아나 등의 꽃봉오리가 자라난다.","en":"Exposure to sunlight adds to its strength. Sunlight also makes the bud on its back grow larger.","ja":"太陽の　光を　浴びるほど体に　力が　わいて　背中のつぼみが　育っていく。","zh-Hans":"沐浴在阳光下越久，身体内会涌出越多力量，背上的花苞也会渐渐成长。","zh-Hant":"沐浴在陽光下越久，身體內會湧出越多力量，背上的花苞也會漸漸成長。","fr":"La lumière du soleil le rend plus fort et vigoureux. Le bulbe sur son dos grossit en conséquence.","de":"Die Sonne macht es stärker. Die Knospe auf seinem Rücken wächst unter dem Einfluss von Sonnenlicht.","es":"La luz del sol lo fortalece y hace que le crezca el capullo que tiene en el lomo.","it":"L’esposizione alla luce solare lo rafforza e fa crescere il bocciolo che ha sul dorso."}',
   'grass', 'poison', 60, 62, 63, 80, 80, 60, 10, 130,
   'medium-slow', 45, 20, 1, false, false, false,
   1, 1, '{"trigger":"level-up","min_level":16}', '{"animated":"/sprites/pokemon/2.gif","animated_shiny":"/sprites/pokemon/shiny/2.gif"}'),
  (3, 'venusaur', 3, true, 1,
   '{"ko":"이상해꽃","en":"Venusaur","ja":"フシギバナ","zh-Hans":"妙蛙花","zh-Hant":"妙蛙花","fr":"Florizarre","de":"Bisaflor","es":"Venusaur","it":"Venusaur"}',
   '{"ko":"씨앗포켓몬","en":"Seed Pokémon","ja":"たねポケモン","zh-Hans":"种子宝可梦","zh-Hant":"種子寶可夢","fr":"Pokémon Graine","de":"Samen-Pokémon","es":"Pokémon Semilla","it":"Pokémon Seme"}',
   '{"ko":"꽃에서 황홀한 향기가 퍼져 나와 싸우는 자의 기분을 달래준다.","en":"A bewitching aroma wafts from its flower. The fragrance becalms those engaged in a battle.","ja":"花から　うっとりする　香りがただよい　戦うものの　気持ちをなだめてしまう。","zh-Hans":"花朵散发出的迷人香味能安抚激动的心情，甚至消弭斗争。","zh-Hant":"花朵散發出的迷人香味，能安撫激動的心情，甚至消弭鬥爭。","fr":"Une douce senteur émane de sa plante. Cette fragrance calme tous ceux qui sont engagés dans un combat.","de":"Die Blume verströmt einen zauberhaften Duft. Er beschwichtigt erhitzte Kämpfer.","es":"La flor que tiene en el lomo libera un delicado aroma, que tiene un efecto relajante en combate.","it":"Il suo fiore emana una fragranza inebriante capace di placare l’animo di chi è impegnato nella lotta."}',
   'grass', 'poison', 80, 82, 83, 100, 100, 80, 20, 1000,
   'medium-slow', 45, 20, 1, false, false, false,
   1, 2, '{"trigger":"level-up","min_level":32}', '{"animated":"/sprites/pokemon/3.gif","animated_shiny":"/sprites/pokemon/shiny/3.gif"}'),
  (4, 'charmander', 4, true, 1,
   '{"ko":"파이리","en":"Charmander","ja":"ヒトカゲ","zh-Hans":"小火龙","zh-Hant":"小火龍","fr":"Salamèche","de":"Glumanda","es":"Charmander","it":"Charmander"}',
   '{"ko":"도롱뇽포켓몬","en":"Lizard Pokémon","ja":"とかげポケモン","zh-Hans":"蜥蜴宝可梦","zh-Hant":"蜥蜴寶可夢","fr":"Pokémon Lézard","de":"Echsen-Pokémon","es":"Pokémon Lagartija","it":"Pokémon Lucertola"}',
   '{"ko":"태어날 때부터 꼬리에 불꽃이 타오르고 있다. 불꽃이 꺼지면 생명도 다하고 만다.","en":"From the time it is born, a flame burns at the tip of its tail. Its life would end if the flame were to go out.","ja":"生まれたときから　しっぽに　炎がともっている。　炎が　消えたときその　命は　終わって　しまう。","zh-Hans":"生下来的时候，尾巴上就有火焰在燃烧。火焰熄灭时，它的生命也会结束。","zh-Hant":"從出生時開始尾巴上就有火焰在燃燒。火焰熄滅時，生命也會結束。","fr":"Depuis sa naissance, une petite flamme brûle au bout de sa queue. Si cette flamme s’éteint, la vie de ce Pokémon s’éteindra elle aussi.","de":"Von Geburt an brennt die Flamme auf seiner Schwanzspitze. Sobald sie verglimmt, erlischt auch sein Lebenslicht.","es":"Este Pokémon nace con una llama en la punta de la cola. Si se le apagara, fallecería.","it":"Una fiamma gli arde sulla punta della coda fin dalla nascita. Se si spegnesse, per lui sarebbe la fine."}',
   'fire', null, 39, 52, 43, 60, 50, 65, 6, 85,
   'medium-slow', 45, 20, 1, false, false, false,
   2, null, null, '{"animated":"/sprites/pokemon/4.gif","animated_shiny":"/sprites/pokemon/shiny/4.gif"}'),
  (5, 'charmeleon', 5, true, 1,
   '{"ko":"리자드","en":"Charmeleon","ja":"リザード","zh-Hans":"火恐龙","zh-Hant":"火恐龍","fr":"Reptincel","de":"Glutexo","es":"Charmeleon","it":"Charmeleon"}',
   '{"ko":"화염포켓몬","en":"Flame Pokémon","ja":"かえんポケモン","zh-Hans":"火焰宝可梦","zh-Hant":"火焰寶可夢","fr":"Pokémon Flamme","de":"Flammen-Pokémon","es":"Pokémon Llama","it":"Pokémon Fiamma"}',
   '{"ko":"싸움으로 기분이 고조되면 작열하는 불꽃을 뿜으며 주변을 태워버린다.","en":"If it becomes agitated during battle, it spouts intense flames, incinerating its surroundings.","ja":"戦いで　気持ちが　たかぶると灼熱の　炎を　吹きながらあたりを　燃やしてまわる。","zh-Hans":"如果它在战斗中亢奋起来，就会喷出灼热的火焰，把周围的东西烧得一干二净。","zh-Hant":"如果牠在戰鬥中亢奮起來，就會噴出灼熱的火焰，把周圍的東西燒得一乾二淨。","fr":"S’il s’excite pendant un combat, il crache de grandes flammes, brûlant tout ce qui se trouve aux alentours.","de":"Steigert es sich in einen Kampf hinein, spuckt es Flammen, die alles in seiner Umgebung niederbrennen.","es":"Si se exalta en combate, expulsa intensas llamaradas que incineran todo a su alrededor.","it":"Se s’infervora nella lotta, sputa potenti fiamme che inceneriscono l’area circostante."}',
   'fire', null, 58, 64, 58, 80, 65, 80, 11, 190,
   'medium-slow', 45, 20, 1, false, false, false,
   2, 4, '{"trigger":"level-up","min_level":16}', '{"animated":"/sprites/pokemon/5.gif","animated_shiny":"/sprites/pokemon/shiny/5.gif"}'),
  (6, 'charizard', 6, true, 1,
   '{"ko":"리자몽","en":"Charizard","ja":"リザードン","zh-Hans":"喷火龙","zh-Hant":"噴火龍","fr":"Dracaufeu","de":"Glurak","es":"Charizard","it":"Charizard"}',
   '{"ko":"화염포켓몬","en":"Flame Pokémon","ja":"かえんポケモン","zh-Hans":"火焰宝可梦","zh-Hant":"火焰寶可夢","fr":"Pokémon Flamme","de":"Flammen-Pokémon","es":"Pokémon Llama","it":"Pokémon Fiamma"}',
   '{"ko":"지상 1400m까지 날개를 사용해 날 수 있다. 고열의 불꽃을 내뿜는다.","en":"Its wings can carry this Pokémon close to an altitude of 4,600 feet. It blows out fire at very high temperatures.","ja":"地上　１４００メートル　まで羽を　使って　飛ぶことができる。高熱の　炎を　吐く。","zh-Hans":"能用翅膀飞到距地面１４００米的高度。会吐出高温火焰。","zh-Hant":"能用翅膀飛到距離地面１４００公尺的高度。會吐出高溫的火焰。","fr":"Ses ailes lui permettent de voler à plus de 1 400 m d’altitude. Ce Pokémon crache du feu à des températures très élevées.","de":"Dieses Pokémon kann mit seinen Flügeln eine Höhe von bis zu 1 400 m erreichen. Es spuckt sehr heißes Feuer.","es":"Sus potentes alas le permiten volar a una altura de 1400 m. Escupe llamaradas que llegan a alcanzar temperaturas elevadísimas.","it":"Grazie alle possenti ali può volare fino a 1.400 m d’altezza. Le fiamme che sputa possono raggiungere temperature altissime."}',
   'fire', 'flying', 78, 84, 78, 109, 85, 100, 17, 905,
   'medium-slow', 45, 20, 1, false, false, false,
   2, 5, '{"trigger":"level-up","min_level":36}', '{"animated":"/sprites/pokemon/6.gif","animated_shiny":"/sprites/pokemon/shiny/6.gif"}'),
  (7, 'squirtle', 7, true, 1,
   '{"ko":"꼬부기","en":"Squirtle","ja":"ゼニガメ","zh-Hans":"杰尼龟","zh-Hant":"傑尼龜","fr":"Carapuce","de":"Schiggy","es":"Squirtle","it":"Squirtle"}',
   '{"ko":"꼬마거북포켓몬","en":"Tiny Turtle Pokémon","ja":"かめのこポケモン","zh-Hans":"小龟宝可梦","zh-Hant":"小龜寶可夢","fr":"Pokémon Minitortue","de":"Minikröten-Pokémon","es":"Pokémon Tortuguita","it":"Pokémon Tartaghina"}',
   '{"ko":"위험해지면 등껍질에 손발을 감추고 몸을 지키면서 입에서 물을 내뿜는다.","en":"When it feels threatened, it draws its limbs inside its shell and sprays water from its mouth.","ja":"危なくなると　甲羅に　手足を引っこめて　身を　守りながら口から　水を　吹き出している。","zh-Hans":"当它遇到危险的时候，会将四肢收回龟壳里保护自己，同时从嘴里喷出水来。","zh-Hant":"當牠遇到危險的時候，會將四肢收回甲殼裡保護自己，同時從嘴裡噴出水來。","fr":"S’il se sent menacé, il rétracte ses pattes dans sa carapace pour se protéger et crache de l’eau.","de":"Fühlt es sich bedroht, verkriecht es sich in seinen Panzer und spuckt Wasser aus seinem Maul.","es":"Cuando se siente en peligro, se esconde en su caparazón y escupe chorros de agua por la boca.","it":"Se si sente minacciato, ritira le zampe nel guscio e inizia a spruzzare acqua dalla bocca."}',
   'water', null, 44, 48, 65, 50, 64, 43, 5, 90,
   'medium-slow', 45, 20, 1, false, false, false,
   3, null, null, '{"animated":"/sprites/pokemon/7.gif","animated_shiny":"/sprites/pokemon/shiny/7.gif"}'),
  (8, 'wartortle', 8, true, 1,
   '{"ko":"어니부기","en":"Wartortle","ja":"カメール","zh-Hans":"卡咪龟","zh-Hant":"卡咪龜","fr":"Carabaffe","de":"Schillok","es":"Wartortle","it":"Wartortle"}',
   '{"ko":"거북포켓몬","en":"Turtle Pokémon","ja":"かめポケモン","zh-Hans":"龟宝可梦","zh-Hant":"龜寶可夢","fr":"Pokémon Tortue","de":"Kröten-Pokémon","es":"Pokémon Tortuga","it":"Pokémon Tartaruga"}',
   '{"ko":"탐스러운 귀와 꼬리를 능숙하게 다뤄서 수중에서의 밸런스를 유지한다.","en":"It cleverly controls its furry ears and tail to maintain its balance while swimming.","ja":"ふさふさの　耳と　しっぽをたくみに　操って　水中でのバランスを　たもつ。","zh-Hans":"会灵巧地摆动自己毛茸茸的耳朵和尾巴，借此在水中保持平衡。","zh-Hant":"會靈巧地擺動自己毛茸茸的耳朵和尾巴，藉此在水中保持平衡。","fr":"Il se sert habilement de sa queue et de ses oreilles touffues pour garder son équilibre sous l’eau.","de":"Es balanciert geschickt mit seinen buschigen Ohren und dem Schweif, während es im Wasser schwimmt.","es":"Utiliza hábilmente sus peludas orejas y la cola para mantener el equilibrio al nadar.","it":"Controlla abilmente le orecchie e la coda coperte di pelo, mantenendo l’assetto mentre nuota."}',
   'water', null, 59, 63, 80, 65, 80, 58, 10, 225,
   'medium-slow', 45, 20, 1, false, false, false,
   3, 7, '{"trigger":"level-up","min_level":16}', '{"animated":"/sprites/pokemon/8.gif","animated_shiny":"/sprites/pokemon/shiny/8.gif"}'),
  (9, 'blastoise', 9, true, 1,
   '{"ko":"거북왕","en":"Blastoise","ja":"カメックス","zh-Hans":"水箭龟","zh-Hant":"水箭龜","fr":"Tortank","de":"Turtok","es":"Blastoise","it":"Blastoise"}',
   '{"ko":"껍질포켓몬","en":"Shellfish Pokémon","ja":"こうらポケモン","zh-Hans":"甲壳宝可梦","zh-Hant":"甲殼寶可夢","fr":"Pokémon Carapace","de":"Panzertier-Pokémon","es":"Pokémon Armazón","it":"Pokémon Crostaceo"}',
   '{"ko":"등껍질의 로켓포에서 뿜어져 나오는 제트 수류는 두꺼운 철판도 뚫는다.","en":"The rocket cannons on its shell fire jets of water capable of punching holes through thick steel.","ja":"甲羅の　ロケット砲　から噴き出した　ジェット水流はぶ厚い　鉄板も　つらぬく。","zh-Hans":"从龟壳上的大炮里放出的喷射水流足以贯穿厚实的铁板。","zh-Hant":"從甲殼上的大炮裡放出的噴射水流足以貫穿厚實的鐵板。","fr":"Les canons sur sa carapace tirent des jets d’eau capables de percer même de l’acier trempé.","de":"Die Wassersalven, die es mit den Wasserdüsen in seinem Panzer abfeuert, durchdringen sogar dicke Stahlwände.","es":"Dispara chorros de agua a través de los cañones de su caparazón, capaces de agujerear incluso el acero.","it":"I cannoni sul suo guscio sparano getti d’acqua capaci di bucare l’acciaio."}',
   'water', null, 79, 83, 100, 85, 105, 78, 16, 855,
   'medium-slow', 45, 20, 1, false, false, false,
   3, 8, '{"trigger":"level-up","min_level":36}', '{"animated":"/sprites/pokemon/9.gif","animated_shiny":"/sprites/pokemon/shiny/9.gif"}'),
  (10, 'caterpie', 10, true, 1,
   '{"ko":"캐터피","en":"Caterpie","ja":"キャタピー","zh-Hans":"绿毛虫","zh-Hant":"綠毛蟲","fr":"Chenipan","de":"Raupy","es":"Caterpie","it":"Caterpie"}',
   '{"ko":"애벌레포켓몬","en":"Worm Pokémon","ja":"いもむしポケモン","zh-Hans":"虫宝宝宝可梦","zh-Hant":"蟲寶寶寶可夢","fr":"Pokémon Ver","de":"Wurm-Pokémon","es":"Pokémon Gusano","it":"Pokémon Baco"}',
   '{"ko":"다리는 짧지만 빨판으로 되어 있어 비탈길이나 벽에서도 지치지 않고 나아간다.","en":"Its short feet are tipped with suction pads that enable it to tirelessly climb slopes and walls.","ja":"脚は　短いが　吸盤になっているので　坂でも　壁でもくたびれることなく　進んでいく。","zh-Hans":"别看它的脚很短，因为是吸盘，所以无论是斜坡还是墙壁都能轻松前进。","zh-Hant":"別看牠的腳很短，因為是吸盤，所以無論是斜坡還是牆壁都能輕鬆前進。","fr":"Ses petites pattes munies de ventouses lui permettent de monter les pentes et de grimper aux murs sans se fatiguer.","de":"Es hat Saugnäpfe an den Beinchen, mit denen es mühelos Steigungen und Mauern erklimmen kann.","es":"Sus cortas patas están recubiertas de ventosas que le permiten subir incansable por muros y cuestas.","it":"Le ventose sulle sue corte zampe gli permettono di affrontare ogni salita e di scalare senza fatica qualsiasi muro."}',
   'bug', null, 45, 30, 35, 20, 20, 45, 3, 29,
   'medium', 255, 15, 4, false, false, false,
   4, null, null, '{"animated":"/sprites/pokemon/10.gif","animated_shiny":"/sprites/pokemon/shiny/10.gif"}'),
  (11, 'metapod', 11, true, 1,
   '{"ko":"단데기","en":"Metapod","ja":"トランセル","zh-Hans":"铁甲蛹","zh-Hant":"鐵甲蛹","fr":"Chrysacier","de":"Safcon","es":"Metapod","it":"Metapod"}',
   '{"ko":"번데기포켓몬","en":"Cocoon Pokémon","ja":"さなぎポケモン","zh-Hans":"蛹宝可梦","zh-Hant":"蛹寶可夢","fr":"Pokémon Cocon","de":"Kokon-Pokémon","es":"Pokémon Capullo","it":"Pokémon Bozzolo"}',
   '{"ko":"단단한 껍질로 둘러싸여 있지만 안은 부드럽기 때문에 강한 공격에는 버티지 못한다.","en":"Even though it is encased in a sturdy shell, the body inside is tender. It can’t withstand a harsh attack.","ja":"硬い　殻に　包まれているが中身は　軟らかいので強い　攻撃には　耐えられない。","zh-Hans":"虽然有坚硬的外壳，因为壳里的身体很软，所以无法抵抗强力的攻击。","zh-Hant":"雖然有堅硬的外殼，但因為殼裡的身體很軟，所以無法抵抗強力的攻擊。","fr":"Bien que son corps soit entouré d’une carapace solide, l’intérieur est si mou qu’il ne résisterait pas à une attaque violente.","de":"In seiner harten Schale ist ein weicher Körper. Einem brutalen Angriff hat es nichts entgegenzusetzen.","es":"Aunque cuenta con una coraza muy dura, tiene un cuerpo bastante blando. Un ataque violento puede acabar con él.","it":"La corazza esterna è robusta ma l’interno è molle. Per questo non è in grado di resistere ad attacchi particolarmente veementi."}',
   'bug', null, 50, 20, 55, 25, 25, 30, 7, 99,
   'medium', 120, 15, 4, false, false, false,
   4, 10, '{"trigger":"level-up","min_level":7}', '{"animated":"/sprites/pokemon/11.gif","animated_shiny":"/sprites/pokemon/shiny/11.gif"}'),
  (12, 'butterfree', 12, true, 1,
   '{"ko":"버터플","en":"Butterfree","ja":"バタフリー","zh-Hans":"巴大蝶","zh-Hant":"巴大蝶","fr":"Papilusion","de":"Smettbo","es":"Butterfree","it":"Butterfree"}',
   '{"ko":"나비포켓몬","en":"Butterfly Pokémon","ja":"ちょうちょポケモン","zh-Hans":"蝴蝶宝可梦","zh-Hant":"蝴蝶寶可夢","fr":"Pokémon Papillon","de":"Falter-Pokémon","es":"Pokémon Mariposa","it":"Pokémon Farfalla"}',
   '{"ko":"매일 꿀을 모으러 다닌다. 다리의 솜털에 꿀을 발라 둥지로 가지고 가는 습성이 있다.","en":"It collects honey every day. It rubs honey onto the hairs on its legs to carry it back to its nest.","ja":"毎日　ミツを　集めまわる。脚の　産毛に　ミツを　塗りこんで巣に　持ち帰る　習性をもつ。","zh-Hans":"每天都忙着采集花蜜。习惯往腿部的细毛上涂满花蜜，然后带回巢穴里。","zh-Hant":"每天都忙著採集花蜜。習慣在腿部的細毛上塗滿花蜜，然後帶回巢穴裡。","fr":"Il ramasse du nectar chaque jour et l’agglutine sur les poils de ses pattes pour le transporter jusqu’à son nid.","de":"Es sammelt täglich Honig. Es reibt ihn in seine Beinhaare, um ihn in sein Nest zu transportieren.","es":"Recoge néctar a diario y se lo adhiere al pelo de las patas para llevarlo a su nido.","it":"Raccoglie nettare tutti i giorni e lo spalma sulla peluria che ricopre le sue zampe per trasportarlo al nido."}',
   'bug', 'flying', 60, 45, 50, 90, 80, 70, 11, 320,
   'medium', 45, 15, 4, false, false, false,
   4, 11, '{"trigger":"level-up","min_level":10}', '{"animated":"/sprites/pokemon/12.gif","animated_shiny":"/sprites/pokemon/shiny/12.gif"}'),
  (13, 'weedle', 13, true, 1,
   '{"ko":"뿔충이","en":"Weedle","ja":"ビードル","zh-Hans":"独角虫","zh-Hant":"獨角蟲","fr":"Aspicot","de":"Hornliu","es":"Weedle","it":"Weedle"}',
   '{"ko":"송충이포켓몬","en":"Hairy Bug Pokémon","ja":"けむしポケモン","zh-Hans":"毛毛虫宝可梦","zh-Hant":"毛毛蟲寶可夢","fr":"Pokémon Insectopic","de":"Raupe","es":"Pokémon Oruga","it":"Pokémon Millepiedi"}',
   '{"ko":"머리에 날카로운 침을 지니고 있다. 우거진 숲이나 풀밭에 숨어 끊임없이 풀잎을 먹고 있다.","en":"Beware of the sharp stinger on its head. It hides in grass and bushes where it eats leaves.","ja":"頭に　鋭い　ハリを　もつ。森や　草地の　茂みに　隠れひたすら　ハッパを　食べている。","zh-Hans":"头上长有尖锐的针。它喜欢藏在森林或草丛里大量吞食树叶。","zh-Hant":"頭上長著尖銳的針。總是躲在森林或是草叢裡，不停地吃著葉子。","fr":"L’aiguillon sur son front est très pointu. Il se cache dans les bois et les hautes herbes, où il se gave de feuilles.","de":"Auf seinem Kopf befindet sich ein spitzer Stachel. Es versteckt sich im hohen Gras sowie in Wäldern und frisst eifrig Blätter.","es":"El aguijón de la cabeza es muy puntiagudo. Se alimenta de hojas oculto en la espesura de bosques y praderas.","it":"Ha un pungiglione acuminato sul capo. Vive tra l’erba alta e nei boschi, dove si nutre di foglie."}',
   'bug', 'poison', 40, 35, 30, 20, 20, 50, 3, 32,
   'medium', 255, 15, 4, false, false, false,
   5, null, null, '{"animated":"/sprites/pokemon/13.gif","animated_shiny":"/sprites/pokemon/shiny/13.gif"}'),
  (14, 'kakuna', 14, true, 1,
   '{"ko":"딱충이","en":"Kakuna","ja":"コクーン","zh-Hans":"铁壳蛹","zh-Hant":"鐵殼蛹","fr":"Coconfort","de":"Kokuna","es":"Kakuna","it":"Kakuna"}',
   '{"ko":"번데기포켓몬","en":"Cocoon Pokémon","ja":"さなぎポケモン","zh-Hans":"蛹宝可梦","zh-Hant":"蛹寶可夢","fr":"Pokémon Cocon","de":"Kokon","es":"Pokémon Capullo","it":"Pokémon Bozzolo"}',
   '{"ko":"스스로는 거의 움직일 수 없지만 위험해지면 침을 세워서 독을 뿜을 때도 있는 듯하다.","en":"Able to move only slightly. When endangered, it may stick out its stinger and poison its enemy.","ja":"自分では　ほとんど　動けないが危なくなると　ハリを出して毒を　与えることも　あるらしい。","zh-Hans":"虽然几乎动也动不了，但是如果遇到了危险，有时似乎会竖起毒刺来反抗。","zh-Hant":"雖然幾乎動也動不了，但如果遭遇到了危險，有時似乎會豎起毒刺來反抗。","fr":"Il peut à peine bouger. Quand il est menacé, il sort parfois son aiguillon pour empoisonner ses ennemis.","de":"Obwohl es sich kaum bewegen kann, ist es bei Gefahr in der Lage, einen Stachel auszufahren, mit dem es seine Gegner vergiftet.","es":"Aunque es casi incapaz de moverse, en caso de sentirse amenazado puede envenenar a los enemigos con su aguijón.","it":"È molto limitato nei movimenti. Se si sente minacciato, estrae il pungiglione e avvelena il nemico."}',
   'bug', 'poison', 45, 25, 50, 25, 25, 35, 6, 100,
   'medium', 120, 15, 4, false, false, false,
   5, 13, '{"trigger":"level-up","min_level":7}', '{"animated":"/sprites/pokemon/14.gif","animated_shiny":"/sprites/pokemon/shiny/14.gif"}'),
  (15, 'beedrill', 15, true, 1,
   '{"ko":"독침붕","en":"Beedrill","ja":"スピアー","zh-Hans":"大针蜂","zh-Hant":"大針蜂","fr":"Dardargnan","de":"Bibor","es":"Beedrill","it":"Beedrill"}',
   '{"ko":"독벌포켓몬","en":"Poison Bee Pokémon","ja":"どくばちポケモン","zh-Hans":"毒蜂宝可梦","zh-Hant":"毒蜂寶可夢","fr":"Pokémon Guêpoison","de":"Giftbiene","es":"Pokémon Abeja Veneno","it":"Pokémon Velenape"}',
   '{"ko":"양손과 엉덩이에 있는 3개의 독침으로 상대를 찌르고 찌르고 또 찌르며 공격한다.","en":"It has three poisonous stingers on its forelegs and its tail. They are used to jab its enemy repeatedly.","ja":"両手と　お尻にある　３本の毒バリで　相手を　刺して刺して　刺しまくって　攻撃する。","zh-Hans":"它会用双手和尾部的３根毒针反复刺伤敌人。","zh-Hant":"會用雙手和屁股上的３根毒針不斷猛刺來攻擊對手。","fr":"Il se sert de ses trois aiguillons empoisonnés situés sur les pattes avant et l’abdomen pour attaquer sans relâche ses adversaires.","de":"Es verfügt über insgesamt drei Giftstachel, zwei an den Armen und einen am Hinterleib, mit denen es seine Gegner wiederholt angreift.","es":"Tiene tres aguijones venenosos, dos en las patas anteriores y uno en la parte baja del abdomen, con los que ataca a sus enemigos una y otra vez.","it":"Possiede tre aculei velenosi, due sulle zampe anteriori e uno sull’addome, con cui punge ripetutamente i nemici."}',
   'bug', 'poison', 65, 90, 40, 45, 80, 75, 10, 295,
   'medium', 45, 15, 4, false, false, false,
   5, 14, '{"trigger":"level-up","min_level":10}', '{"animated":"/sprites/pokemon/15.gif","animated_shiny":"/sprites/pokemon/shiny/15.gif"}'),
  (16, 'pidgey', 16, true, 1,
   '{"ko":"구구","en":"Pidgey","ja":"ポッポ","zh-Hans":"波波","zh-Hant":"波波","fr":"Roucool","de":"Taubsi","es":"Pidgey","it":"Pidgey"}',
   '{"ko":"아기새포켓몬","en":"Tiny Bird Pokémon","ja":"ことりポケモン","zh-Hans":"小鸟宝可梦","zh-Hant":"小鳥寶可夢","fr":"Pokémon Minoiseau","de":"Kleinvogel","es":"Pokémon Pajarito","it":"Pokémon Uccellino"}',
   '{"ko":"얌전한 성격이라 습격당해도 반격하지 않고 모래를 뿌려서 몸을 지키는 경우가 많다.","en":"Very docile. If attacked, it will often kick up sand to protect itself rather than fight back.","ja":"おとなしい　性格で　襲われても反撃　せずに　砂を　かけて身を　守ることが　多い。","zh-Hans":"性格沉着冷静，即使受到攻击也很少反击，只会朝对手扬起沙子保护自己。","zh-Hant":"性情溫馴，即使遭到襲擊也很少反擊，只會朝對手潑沙子來保護自己。","fr":"De nature très docile, il préfère projeter du sable pour se défendre plutôt que contre-attaquer.","de":"Ein sanftmütiges Pokémon, welches lieber Sand zum Schutz aufwirbelt, als zurückzuschlagen.","es":"Su docilidad es tal que suelen defenderse levantando arena en lugar de contraatacar.","it":"Di indole docile, preferisce gettare sabbia verso il nemico per proteggersi piuttosto che attaccarlo."}',
   'normal', 'flying', 40, 45, 40, 35, 35, 56, 3, 18,
   'medium-slow', 255, 15, 4, false, false, false,
   6, null, null, '{"animated":"/sprites/pokemon/16.gif","animated_shiny":"/sprites/pokemon/shiny/16.gif"}'),
  (17, 'pidgeotto', 17, true, 1,
   '{"ko":"피죤","en":"Pidgeotto","ja":"ピジョン","zh-Hans":"比比鸟","zh-Hant":"比比鳥","fr":"Roucoups","de":"Tauboga","es":"Pidgeotto","it":"Pidgeotto"}',
   '{"ko":"새포켓몬","en":"Bird Pokémon","ja":"とりポケモン","zh-Hans":"鸟宝可梦","zh-Hant":"鳥寶可夢","fr":"Pokémon Oiseau","de":"Vogel","es":"Pokémon Pájaro","it":"Pokémon Uccello"}',
   '{"ko":"어마어마한 체력의 소유자로 넓은 영역을 날아다니며 먼 곳까지 먹이를 찾으러 간다.","en":"This Pokémon is full of vitality. It constantly flies around its large territory in search of prey.","ja":"あり余る　体力の　持ち主で広い　縄張りを　飛びまわり遠くまで　エサを　探しにいく。","zh-Hans":"拥有超群的体力，而且飞翔范围广，经常飞到很远的地方寻找食物。","zh-Hant":"擁有著超乎尋常的體力，會在廣大的地盤裡四處飛行，到遠處去尋找食物。","fr":"Ce Pokémon est très endurant. Il survole en permanence son territoire pour chasser.","de":"Dieses kraftvolle Pokémon wacht unermüdlich über sein riesiges Territorium und fliegt weite Strecken auf der Suche nach Beute.","es":"Su extraordinaria vitalidad y resistencia le permiten cubrir grandes distancias del territorio que habita en busca de presas.","it":"Un Pokémon pieno di vitalità che vola instancabile sul suo territorio in cerca di prede."}',
   'normal', 'flying', 63, 60, 55, 50, 50, 71, 11, 300,
   'medium-slow', 120, 15, 4, false, false, false,
   6, 16, '{"trigger":"level-up","min_level":18}', '{"animated":"/sprites/pokemon/17.gif","animated_shiny":"/sprites/pokemon/shiny/17.gif"}'),
  (18, 'pidgeot', 18, true, 1,
   '{"ko":"피죤투","en":"Pidgeot","ja":"ピジョット","zh-Hans":"大比鸟","zh-Hant":"大比鳥","fr":"Roucarnage","de":"Tauboss","es":"Pidgeot","it":"Pidgeot"}',
   '{"ko":"새포켓몬","en":"Bird Pokémon","ja":"とりポケモン","zh-Hans":"鸟宝可梦","zh-Hant":"鳥寶可夢","fr":"Pokémon Oiseau","de":"Vogel","es":"Pokémon Pájaro","it":"Pokémon Uccello"}',
   '{"ko":"마하2의 속도로 비행하여 먹이를 찾는다. 그 커다란 발톱은 무기로서도 두려움의 대상이다.","en":"This Pokémon flies at Mach 2 speed, seeking prey. Its large talons are feared as wicked weapons.","ja":"マッハ２で　飛行し　エサを探す。その　大きな　ツメは　武器としても　恐れられている。","zh-Hans":"以２马赫的飞行速度来觅食。它巨大的爪子是非常令人惧怕的武器。","zh-Hant":"會以２馬赫的速度飛行來尋找食物。巨大的爪子是很可怕的武器。","fr":"Ce Pokémon vole à Mach 2 quand il chasse. Ses grandes serres sont des armes redoutables.","de":"Auf der Jagd nach Beute fliegt es mit einer Geschwindigkeit von bis zu Mach 2. Seine mächtigen Klauen gelten als gefürchtete Waffen.","es":"Este Pokémon vuela a una velocidad de 2 mach en busca de presas. Sus grandes garras son armas muy peligrosas.","it":"Può volare a una velocità di Mach 2 in cerca di prede. I suoi artigli sono armi micidiali."}',
   'normal', 'flying', 83, 80, 75, 70, 70, 101, 15, 395,
   'medium-slow', 45, 15, 4, false, false, false,
   6, 17, '{"trigger":"level-up","min_level":36}', '{"animated":"/sprites/pokemon/18.gif","animated_shiny":"/sprites/pokemon/shiny/18.gif"}'),
  (19, 'rattata', 19, true, 1,
   '{"ko":"꼬렛","en":"Rattata","ja":"コラッタ","zh-Hans":"小拉达","zh-Hant":"小拉達","fr":"Rattata","de":"Rattfratz","es":"Rattata","it":"Rattata"}',
   '{"ko":"쥐포켓몬","en":"Mouse Pokémon","ja":"ねずみポケモン","zh-Hans":"鼠宝可梦","zh-Hant":"鼠寶可夢","fr":"Pokémon Souris","de":"Maus","es":"Pokémon Ratón","it":"Pokémon Topo"}',
   '{"ko":"2개의 이빨로 뭐든지 일단 갉고 본다. 1마리를 발견했다면 그곳에 40마리는 살고 있을 것이다.","en":"Will chew on anything with its fangs. If you see one, you can be certain that 40 more live in the area.","ja":"キバが２つ。とにかく　なんでもかじってみる。１匹　見つけたら４０匹は　そこに　住んでるはず。","zh-Hans":"有两颗大门牙，见什么咬什么。只要看到１只小拉达出没，附近肯定还住着40只以上。","zh-Hant":"長著２顆大牙，碰到什麼都會先咬上一口。只要看見１隻出沒，附近肯定還住著40隻以上。","fr":"Il peut ronger n’importe quoi avec ses deux dents. Quand on en voit un, il y en a certainement 40 dans le coin.","de":"Es knabbert mit seinen zwei Nagezähnen alles und jeden an. Stößt man auf eines, findet man sicherlich 40 weitere in der Gegend.","es":"Es propenso a hincar los incisivos en cualquier cosa que se le ponga por delante. Si se ve alguno, seguramente haya cuarenta cerca.","it":"Con i suoi incisivi rode qualsiasi cosa. Se se ne avvista uno, è probabile che in zona vivano almeno 40 esemplari."}',
   'normal', null, 30, 56, 35, 25, 35, 72, 3, 35,
   'medium', 255, 15, 4, false, false, false,
   7, null, null, '{"animated":"/sprites/pokemon/19.gif","animated_shiny":"/sprites/pokemon/shiny/19.gif"}'),
  (20, 'raticate', 20, true, 1,
   '{"ko":"레트라","en":"Raticate","ja":"ラッタ","zh-Hans":"拉达","zh-Hant":"拉達","fr":"Rattatac","de":"Rattikarl","es":"Raticate","it":"Raticate"}',
   '{"ko":"쥐포켓몬","en":"Mouse Pokémon","ja":"ねずみポケモン","zh-Hans":"鼠宝可梦","zh-Hant":"鼠寶可夢","fr":"Pokémon Souris","de":"Maus","es":"Pokémon Ratón","it":"Pokémon Topo"}',
   '{"ko":"뒷다리에 달린 작은 물갈퀴로 강을 헤엄치는 이유는 물속에 있는 먹이를 잡기 위해서다.","en":"Its hind feet are webbed. They act as flippers, so it can swim in rivers and hunt for prey.","ja":"後ろ足にある　小さな　水かきで川を　泳ぐのは　水の中のエサを　捕るためだ。","zh-Hans":"它的后脚上长着小蹼，以便它在水中游泳寻找食物。","zh-Hant":"為了取得水中的食物，牠會利用後腳上的小蹼在河裡游泳。","fr":"Ses pattes arrière sont palmées. Il peut donc poursuivre sa proie dans les cours d’eau et les rivières.","de":"Die Hinterbeine dieses Pokémon verfügen über kleine Schwimmhäute. So kann es in Flüssen jagen.","es":"Gracias a las pequeñas membranas de las patas traseras, puede nadar por los ríos para capturar presas.","it":"Dispone di zampe posteriori palmate che gli permettono di nuotare nei fiumi in cerca di prede."}',
   'normal', null, 55, 81, 60, 50, 70, 97, 7, 185,
   'medium', 127, 15, 4, false, false, false,
   7, 19, '{"trigger":"level-up","min_level":20}', '{"animated":"/sprites/pokemon/20.gif","animated_shiny":"/sprites/pokemon/shiny/20.gif"}'),
  (21, 'spearow', 21, true, 1,
   '{"ko":"깨비참","en":"Spearow","ja":"オニスズメ","zh-Hans":"烈雀","zh-Hant":"烈雀","fr":"Piafabec","de":"Habitak","es":"Spearow","it":"Spearow"}',
   '{"ko":"아기새포켓몬","en":"Tiny Bird Pokémon","ja":"ことりポケモン","zh-Hans":"小鸟宝可梦","zh-Hant":"小鳥寶可夢","fr":"Pokémon Minoiseau","de":"Kleinvogel","es":"Pokémon Pajarito","it":"Pokémon Uccellino"}',
   '{"ko":"높이 나는 것에 서투르다. 영역을 지키기 위해 맹렬한 스피드로 날아다닌다.","en":"Inept at flying high. However, it can fly around very fast to protect its territory.","ja":"高く　飛ぶのは　苦手。縄張りを　守るために猛スピードで　飛びまわっている。","zh-Hans":"不擅长高空飞行。会以超高速在地盘里四处盘旋，以保护自己的地盘不被侵犯。","zh-Hant":"不擅長高空飛行。會以超高速在地盤裡四處盤旋，確保自己的地盤不被侵犯。","fr":"Il est incapable de voler à haute altitude. Il se déplace très vite pour protéger son territoire.","de":"In großen Höhen fällt ihm das Fliegen schwer. Allerdings kann es pfeilschnell umherflitzen, wenn es um den Schutz seines Habitats geht.","es":"A la hora de proteger su territorio, compensa su incapacidad para volar a gran altura con una increíble velocidad.","it":"Incapace di raggiungere alte quote, sorvola il suo territorio a gran velocità per proteggerlo."}',
   'normal', 'flying', 40, 60, 30, 31, 31, 70, 3, 20,
   'medium', 255, 15, 4, false, false, false,
   8, null, null, '{"animated":"/sprites/pokemon/21.gif","animated_shiny":"/sprites/pokemon/shiny/21.gif"}'),
  (22, 'fearow', 22, true, 1,
   '{"ko":"깨비드릴조","en":"Fearow","ja":"オニドリル","zh-Hans":"大嘴雀","zh-Hant":"大嘴雀","fr":"Rapasdepic","de":"Ibitak","es":"Fearow","it":"Fearow"}',
   '{"ko":"부리포켓몬","en":"Beak Pokémon","ja":"くちばしポケモン","zh-Hans":"鸟嘴宝可梦","zh-Hant":"鳥嘴寶可夢","fr":"Pokémon Bec-Oiseau","de":"Pickvogel","es":"Pokémon Pico","it":"Pokémon Becco"}',
   '{"ko":"옛날부터 살고 있는 포켓몬. 조금이라도 위험을 감지하면 하늘 높이 날아가 버린다.","en":"A Pokémon that dates back many years. If it senses danger, it flies high and away, instantly.","ja":"昔から　住んでいる　ポケモン。少しでも　危険を　感じると空高く　飛んで　いってしまう。","zh-Hans":"很久以前就存在的宝可梦。哪怕只察觉到一丝危险，都会立即飞向高空。","zh-Hant":"從很久以前就已存在的寶可夢。只要察覺到絲毫的危險，就會立刻飛上高空躲避。","fr":"Un Pokémon très ancien. S’il perçoit un danger, il fuit instantanément à haute altitude.","de":"Dieses Pokémon gehört einer sehr alten Spezies an. Wittert es Gefahr, so fliegt es sofort in große Höhen davon.","es":"Este Pokémon ha existido desde tiempos remotos. Al menor atisbo de peligro, alza el vuelo y huye.","it":"Questo Pokémon molto antico vola in alto nel cielo al minimo accenno di pericolo."}',
   'normal', 'flying', 65, 90, 65, 61, 61, 100, 12, 380,
   'medium', 90, 15, 4, false, false, false,
   8, 21, '{"trigger":"level-up","min_level":20}', '{"animated":"/sprites/pokemon/22.gif","animated_shiny":"/sprites/pokemon/shiny/22.gif"}'),
  (23, 'ekans', 23, true, 1,
   '{"ko":"아보","en":"Ekans","ja":"アーボ","zh-Hans":"阿柏蛇","zh-Hant":"阿柏蛇","fr":"Abo","de":"Rettan","es":"Ekans","it":"Ekans"}',
   '{"ko":"뱀포켓몬","en":"Snake Pokémon","ja":"へびポケモン","zh-Hans":"蛇宝可梦","zh-Hant":"蛇寶可夢","fr":"Pokémon Serpent","de":"Schlange","es":"Pokémon Serpiente","it":"Pokémon Serpente"}',
   '{"ko":"성장할수록 점점 길어진다. 밤에는 나뭇가지에 몸을 돌돌 말고 쉰다.","en":"The older it gets, the longer it grows. At night, it wraps its long body around tree branches to rest.","ja":"育つほどに　どんどん　長くなる。そして　夜中は　木の枝にグルグルと　からまって　休む。","zh-Hans":"身体会随着年龄增长不断变长。每到夜里，它会一圈圈地将身体缠绕在树枝上休息。","zh-Hant":"身體會隨著年齡增長不斷變長。每到夜裡就會把身體纏繞在樹枝上歇息。","fr":"Plus il est âgé, plus son corps est long. La nuit, il s’enroule autour de branches d’arbres pour se reposer.","de":"Mit dem Alter wird der Körper dieses Pokémon immer länger. Nachts wickelt es sich um Äste, um zu ruhen.","es":"La longitud de este Pokémon aumenta con el tiempo. Por la noche, se enrosca en las ramas de los árboles para descansar.","it":"Si allunga sempre più con l’età. La notte si avvolge attorno a qualche ramo per dormire."}',
   'poison', null, 35, 60, 44, 40, 54, 55, 20, 69,
   'medium', 255, 20, 4, false, false, false,
   9, null, null, '{"animated":"/sprites/pokemon/23.gif","animated_shiny":"/sprites/pokemon/shiny/23.gif"}'),
  (24, 'arbok', 24, true, 1,
   '{"ko":"아보크","en":"Arbok","ja":"アーボック","zh-Hans":"阿柏怪","zh-Hant":"阿柏怪","fr":"Arbok","de":"Arbok","es":"Arbok","it":"Arbok"}',
   '{"ko":"코브라포켓몬","en":"Cobra Pokémon","ja":"コブラポケモン","zh-Hans":"眼镜蛇宝可梦","zh-Hant":"眼鏡蛇寶可夢","fr":"Pokémon Cobra","de":"Kobra","es":"Pokémon Cobra","it":"Pokémon Cobra"}',
   '{"ko":"무서워 보이는 배의 무늬는 연구 결과 6종류 정도의 패턴이 확인되었다.","en":"The frightening patterns on its belly have been studied. Six variations have been confirmed.","ja":"恐ろしげな　お腹の　模様は研究の　結果　６種類ほどパターンが　確認されている。","zh-Hans":"根据研究证实，它腹部那可怕的纹路大约有６个种类已经得到确认。","zh-Hant":"根據目前已知的研究結果，長在牠肚子上的可怕花紋一共有６種不同的類型。","fr":"Des études ont révélé que les marques effrayantes de son corps pouvaient former six motifs différents.","de":"Von dem furchterregenden Muster auf seinem Bauch wurden durch Studien bislang sechs verschiedene Varianten entdeckt.","es":"Se han llegado a identificar hasta seis variaciones distintas de los espeluznantes dibujos de su piel.","it":"Gli spaventosi disegni che ha sulla pancia sono oggetto di studio. Ne sono state scoperte sei diverse variazioni."}',
   'poison', null, 60, 95, 69, 65, 79, 80, 35, 650,
   'medium', 90, 20, 4, false, false, false,
   9, 23, '{"trigger":"level-up","min_level":22}', '{"animated":"/sprites/pokemon/24.gif","animated_shiny":"/sprites/pokemon/shiny/24.gif"}'),
  (25, 'pikachu', 25, true, 1,
   '{"ko":"피카츄","en":"Pikachu","ja":"ピカチュウ","zh-Hans":"皮卡丘","zh-Hant":"皮卡丘","fr":"Pikachu","de":"Pikachu","es":"Pikachu","it":"Pikachu"}',
   '{"ko":"쥐포켓몬","en":"Mouse Pokémon","ja":"ねずみポケモン","zh-Hans":"鼠宝可梦","zh-Hant":"鼠寶可夢","fr":"Pokémon Souris","de":"Maus-Pokémon","es":"Pokémon Ratón","it":"Pokémon Topo"}',
   '{"ko":"서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.","en":"Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.","ja":"おたがいの　しっぽを　くっつけて電気を　流しあうのがピカチュウ　同士の　挨拶だ。","zh-Hans":"皮卡丘们把尾巴贴在一起交换电流，其实是在互相打招呼。","zh-Hant":"皮卡丘們把尾巴貼在一起交換電流，其實是在互相打招呼。","fr":"Les Pikachu se disent bonjour en se frottant la queue et en y faisant passer du courant électrique.","de":"Pikachu begrüßen einander, indem sie ihre Schweife aneinanderreiben und eine Ladung Strom durch diese gleiten lassen.","es":"Los miembros de esta especie se saludan entre sí uniendo sus colas y transmitiéndose corriente eléctrica.","it":"I Pikachu si salutano fra loro unendo le code e facendovi passare elettricità attraverso."}',
   'electric', null, 35, 55, 40, 50, 50, 90, 4, 60,
   'medium', 190, 10, 4, false, false, false,
   10, null, null, '{"animated":"/sprites/pokemon/25.gif","animated_shiny":"/sprites/pokemon/shiny/25.gif"}'),
  (26, 'raichu', 26, true, 1,
   '{"ko":"라이츄","en":"Raichu","ja":"ライチュウ","zh-Hans":"雷丘","zh-Hant":"雷丘","fr":"Raichu","de":"Raichu","es":"Raichu","it":"Raichu"}',
   '{"ko":"쥐포켓몬","en":"Mouse Pokémon","ja":"ねずみポケモン","zh-Hans":"鼠宝可梦","zh-Hant":"鼠寶可夢","fr":"Pokémon Souris","de":"Maus-Pokémon","es":"Pokémon Ratón","it":"Pokémon Topo"}',
   '{"ko":"전기 주머니가 텅 비면 꼬리를 똑바로 세워서 공기 중의 전기를 모은다.","en":"It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.","ja":"電気袋が　空っぽに　なるとしっぽを　まっすぐ　立てて空気中の　電気を　集める。","zh-Hans":"如果电囊空了，它就会直直地竖起尾巴，收集空气中的电流。","zh-Hant":"如果電囊空了，牠就會直直地豎起尾巴，收集空氣中的電流。","fr":"Si ses joues sont à court d’énergie, il lève la queue et capte l’électricité contenue dans l’atmosphère.","de":"Wenn der in seinen Backentaschen gespeicherte Strom leer ist, stellt es seinen Schweif auf, um Elektrizität aus der Luft zu ziehen.","es":"Cuando ha descargado las bolsas de las mejillas, levanta la cola y absorbe la carga eléctrica que hay en el ambiente.","it":"Quando le sacche elettriche sono scariche, rizza la coda per raccogliere elettricità dall’atmosfera."}',
   'electric', null, 60, 90, 55, 90, 80, 110, 8, 300,
   'medium', 75, 10, 4, false, false, false,
   10, 25, '{"trigger":"use-item","item":{"id":"thunder-stone","names":{"ko":"천둥의돌","en":"Thunder Stone","ja":"かみなりのいし","zh-Hans":"雷之石","zh-Hant":"雷之石","fr":"Pierre Foudre","de":"Donnerstein","es":"Piedra Trueno","it":"Pietratuono"}}}', '{"animated":"/sprites/pokemon/26.gif","animated_shiny":"/sprites/pokemon/shiny/26.gif"}'),
  (27, 'sandshrew', 27, true, 1,
   '{"ko":"모래두지","en":"Sandshrew","ja":"サンド","zh-Hans":"穿山鼠","zh-Hant":"穿山鼠","fr":"Sabelette","de":"Sandan","es":"Sandshrew","it":"Sandshrew"}',
   '{"ko":"쥐포켓몬","en":"Mouse Pokémon","ja":"ねずみポケモン","zh-Hans":"鼠宝可梦","zh-Hant":"鼠寶可夢","fr":"Pokémon Souris","de":"Maus-Pokémon","es":"Pokémon Ratón","it":"Pokémon Topo"}',
   '{"ko":"땅을 파서 굴을 만든다. 땅속의 단단한 바위도 날카로운 발톱으로 부수며 파고들어 간다.","en":"It burrows into the ground to create its nest. If hard stones impede its tunneling, it uses its sharp claws to shatter them and then carries on digging.","ja":"地面を　掘って　巣穴を　つくる。地中の　硬い　岩も　鋭い　ツメで砕いて　掘り進むぞ。","zh-Hans":"会在地上挖洞建造巢穴。挖洞时，即便遇到地里的坚硬岩石，也能用尖锐的爪子弄碎后继续挖进。","zh-Hant":"會在地面挖洞築巢。即使遇到地下堅硬的岩石，也會用銳利的爪子擊碎並向前挖進。","fr":"Il creuse le sol pour construire sa tanière. Rien n’arrête ses griffes acérées, pas même la roche la plus solide.","de":"Es gräbt sich seinen Bau im Erdboden. Stößt es dabei auf harte Steine, zerstört es diese mit seinen scharfen Krallen und gräbt unbeirrt weiter.","es":"Excava madrigueras profundas en las que vive. Parte con sus afiladas garras cualquier roca, por dura que sea, que le entorpezca el camino.","it":"Scava nel terreno per costruire la sua tana, frantumando anche le rocce più dure con i suoi artigli affilati."}',
   'ground', null, 50, 75, 85, 20, 30, 40, 6, 120,
   'medium', 255, 20, 4, false, false, false,
   11, null, null, '{"animated":"/sprites/pokemon/27.gif","animated_shiny":"/sprites/pokemon/shiny/27.gif"}'),
  (28, 'sandslash', 28, true, 1,
   '{"ko":"고지","en":"Sandslash","ja":"サンドパン","zh-Hans":"穿山王","zh-Hant":"穿山王","fr":"Sablaireau","de":"Sandamer","es":"Sandslash","it":"Sandslash"}',
   '{"ko":"쥐포켓몬","en":"Mouse Pokémon","ja":"ねずみポケモン","zh-Hans":"鼠宝可梦","zh-Hant":"鼠寶可夢","fr":"Pokémon Souris","de":"Maus-Pokémon","es":"Pokémon Ratón","it":"Pokémon Topo"}',
   '{"ko":"날카로운 발톱으로 찍으며 나무에 오른다. 아래에서 기다리는 모래두지들에게 나무열매를 떨어뜨려 나눠준다.","en":"It climbs trees by hooking on with its sharp claws. Sandslash shares the berries it gathers, dropping them down to Sandshrew waiting below the tree.","ja":"鋭い　ツメを　ひっかけて　木を登る。　下で　待つ　サンドたちに木の実を　落とし　分け与えるのだ。","zh-Hans":"会将锐利的爪子钩在树上爬树。这是为了设法使树果掉落，分给等在树下的穿山鼠们。","zh-Hant":"會用銳利的爪子當作鉤子來爬樹。這是為了將樹果擊落，分給在樹下等待的穿山鼠們。","fr":"Il grimpe aux arbres grâce à ses griffes acérées et fait tomber des Baies pour les Sabelette qui attendent au sol.","de":"Mit seinen scharfen Krallen klettert es auf Bäume und wirft unten wartenden Sandan Beeren zu, die sie sich dann teilen.","es":"Trepa a los árboles con sus afiladas garras y deja caer bayas para los Sandshrew que esperan debajo.","it":"Si arrampica sugli alberi utilizzando i suoi artigli affilati per poi condividere le bacche che trova con i Sandshrew, che aspettano sotto."}',
   'ground', null, 75, 100, 110, 45, 55, 65, 10, 295,
   'medium', 90, 20, 4, false, false, false,
   11, 27, '{"trigger":"level-up","min_level":22}', '{"animated":"/sprites/pokemon/28.gif","animated_shiny":"/sprites/pokemon/shiny/28.gif"}'),
  (29, 'nidoran-f', 29, true, 1,
   '{"ko":"니드런♀","en":"Nidoran♀","ja":"ニドラン♀","zh-Hans":"尼多兰","zh-Hant":"尼多蘭","fr":"Nidoran♀","de":"Nidoran♀","es":"Nidoran♀","it":"Nidoran♀"}',
   '{"ko":"독침포켓몬","en":"Poison Pin Pokémon","ja":"どくばりポケモン","zh-Hans":"毒针宝可梦","zh-Hant":"毒針寶可夢","fr":"Pokémon Vénépic","de":"Giftdorn-Pokémon","es":"Pokémon Pin Veneno","it":"Pokémon Velenago"}',
   '{"ko":"단단한 앞니로 나무열매를 깨물어 먹는다. 뿔의 끝은 수컷보다 조금 둥그스름하다.","en":"It uses its hard incisor teeth to crush and eat berries. The tip of a female Nidoran’s horn is a bit more rounded than the tip of a male’s horn.","ja":"硬い　前歯で　木の実を　砕いて　食べる。ツノの　先は　オスより　少し丸みを　帯びている。","zh-Hans":"用坚硬的门牙咬碎树果吃。和雄性相比，角的尖端稍圆一些。","zh-Hant":"會用堅硬的門牙咬碎樹果後吃下。角的尖端會比雄性還要圓一些。","fr":"Ce Pokémon se nourrit de Baies en les ouvrant avec ses incisives. Le bout de sa corne est plus arrondi que celui du mâle.","de":"Mit ihren harten Vorderzähnen zerteilen sie Beeren, bevor sie diese essen. Die Spitze ihres Horns ist etwas abgerundeter als bei Männchen.","es":"Parte las bayas con sus duros incisivos para comérselas. La punta del cuerno de las hembras es más redondeada que la de los machos.","it":"Mangia le bacche frantumandole con i robusti incisivi. La punta del corno è leggermente più arrotondata rispetto a quella del maschio."}',
   'poison', null, 55, 47, 52, 40, 40, 41, 4, 70,
   'medium-slow', 235, 20, 8, false, false, false,
   12, null, null, '{"animated":"/sprites/pokemon/29.gif","animated_shiny":"/sprites/pokemon/shiny/29.gif"}'),
  (30, 'nidorina', 30, true, 1,
   '{"ko":"니드리나","en":"Nidorina","ja":"ニドリーナ","zh-Hans":"尼多娜","zh-Hant":"尼多娜","fr":"Nidorina","de":"Nidorina","es":"Nidorina","it":"Nidorina"}',
   '{"ko":"독침포켓몬","en":"Poison Pin Pokémon","ja":"どくばりポケモン","zh-Hans":"毒针宝可梦","zh-Hant":"毒針寶可夢","fr":"Pokémon Vénépic","de":"Giftdorn-Pokémon","es":"Pokémon Pin Veneno","it":"Pokémon Velenago"}',
   '{"ko":"무리에 위험이 닥치면 동료와 결속하여 초음파로 크게 합창한다.","en":"If the group is threatened, these Pokémon will band together to assault enemies with a chorus of ultrasonic waves.","ja":"群れに　危険が　せまると　仲間で結束して　超音波の　大合唱をおみまいするぞ。","zh-Hans":"如果族群遇到了危险，会和伙伴们团结起来，施展出超音波大合唱。","zh-Hant":"有危險逼近群體時，會與夥伴們團結一致地用超音波的大合唱來攻擊。","fr":"Si un danger menace le groupe, ces Pokémon se réunissent et l’affrontent en émettant des ultrasons en chœur.","de":"Nähert sich Gefahr, schließen sie sich mit anderen Artgenossen zusammen und begegnen der Bedrohung mit einem Chor aus Ultraschallwellen.","es":"Cuando el peligro se cierne sobre la manada, los miembros unen fuerzas para defenderse emitiendo un coro de ondas ultrasónicas.","it":"Quando il branco è minacciato da un pericolo, i suoi membri uniscono le forze e dispiegano un coro di ultrasuoni."}',
   'poison', null, 70, 62, 67, 55, 55, 56, 8, 200,
   'medium-slow', 120, 20, 8, false, false, false,
   12, 29, '{"trigger":"level-up","min_level":16}', '{"animated":"/sprites/pokemon/30.gif","animated_shiny":"/sprites/pokemon/shiny/30.gif"}'),
  (31, 'nidoqueen', 31, true, 1,
   '{"ko":"니드퀸","en":"Nidoqueen","ja":"ニドクイン","zh-Hans":"尼多后","zh-Hant":"尼多后","fr":"Nidoqueen","de":"Nidoqueen","es":"Nidoqueen","it":"Nidoqueen"}',
   '{"ko":"드릴포켓몬","en":"Drill Pokémon","ja":"ドリルポケモン","zh-Hans":"钻锥宝可梦","zh-Hant":"鑽錐寶可夢","fr":"Pokémon Perceur","de":"Bohrer-Pokémon","es":"Pokémon Taladro","it":"Pokémon Trapano"}',
   '{"ko":"등의 가시 틈에 새끼를 태우고 달랜다. 이때는 독이 절대 나오지 않는다.","en":"It pacifies offspring by placing them in the gaps between the spines on its back. The spines will never secrete poison while young are present.","ja":"背中の　棘の　隙間に　子どもを乗せて　あやす。　そのときに　毒が出ることは　けっして　ないのだ。","zh-Hans":"把孩子放在背上刺与刺的空隙里来哄它们。在这时绝对不会释放毒素。","zh-Hant":"會把孩子放在背上的刺與刺之間來哄牠們。這時候絕對不會釋放毒素。","fr":"Ce Pokémon calme les petits de son espèce en les plaçant entre ses épines dorsales. Dans ce cas, elles ne libèrent pas de poison.","de":"Es beruhigt seine Jungen, indem es diese zwischen den Stacheln auf seinem Rücken reiten lässt. Die Stacheln sondern derweil kein Gift ab.","es":"Para mecer a sus crías, las coloca en los huecos que tiene entre las púas dorsales, momento durante el cual no secretan veneno.","it":"Coccola i cuccioli mettendoseli sulla schiena negli spazi fra gli aculei, che in quei momenti smettono di secernere veleno."}',
   'poison', 'ground', 90, 92, 87, 75, 85, 76, 13, 600,
   'medium-slow', 45, 20, 8, false, false, false,
   12, 30, '{"trigger":"use-item","item":{"id":"moon-stone","names":{"ko":"달의돌","en":"Moon Stone","ja":"つきのいし","zh-Hans":"月之石","zh-Hant":"月之石","fr":"Pierre Lune","de":"Mondstein","es":"Piedra Lunar","it":"Pietralunare"}}}', '{"animated":"/sprites/pokemon/31.gif","animated_shiny":"/sprites/pokemon/shiny/31.gif"}'),
  (32, 'nidoran-m', 32, true, 1,
   '{"ko":"니드런♂","en":"Nidoran♂","ja":"ニドラン♂","zh-Hans":"尼多朗","zh-Hant":"尼多朗","fr":"Nidoran♂","de":"Nidoran♂","es":"Nidoran♂","it":"Nidoran♂"}',
   '{"ko":"독침포켓몬","en":"Poison Pin Pokémon","ja":"どくばりポケモン","zh-Hans":"毒针宝可梦","zh-Hant":"毒針寶可夢","fr":"Pokémon Vénépic","de":"Giftdorn-Pokémon","es":"Pokémon Pin Veneno","it":"Pokémon Velenago"}',
   '{"ko":"몸집은 작지만 용맹한 성질을 지녔다. 친한 암컷을 지키기 위해 몸을 던져 과감히 싸운다.","en":"Small but brave, this Pokémon will hold its ground and even risk its life in battle to protect the female it’s friendly with.","ja":"小柄だが　勇ましい　性質。仲良しの　メスを　守るため身を　ていして　果敢に　戦う。","zh-Hans":"身材虽小，却性格勇敢。为了保护相好的雌性，会不顾生命果敢地战斗。","zh-Hant":"體型嬌小，但性情勇猛。為了保護感情好的雌性，會奮不顧身地勇敢戰鬥。","fr":"Malgré sa petite taille, il est très téméraire. Afin de protéger sa compagne, il est prêt à se battre et à risquer sa vie.","de":"Trotz seiner geringen Größe ist es sehr mutig. Um ein befreundetes Weibchen zu beschützen, riskiert es sein Leben und kämpft unerschrocken.","es":"Pequeño pero valiente. Arriesgaría la vida en combate con tal de proteger a su compañera.","it":"Impavido nonostante la corporatura minuta, lotta con coraggio per proteggere la femmina a cui è affezionato, anche a costo della vita."}',
   'poison', null, 46, 57, 40, 40, 40, 50, 5, 90,
   'medium-slow', 235, 20, 0, false, false, false,
   13, null, null, '{"animated":"/sprites/pokemon/32.gif","animated_shiny":"/sprites/pokemon/shiny/32.gif"}'),
  (33, 'nidorino', 33, true, 1,
   '{"ko":"니드리노","en":"Nidorino","ja":"ニドリーノ","zh-Hans":"尼多力诺","zh-Hant":"尼多力諾","fr":"Nidorino","de":"Nidorino","es":"Nidorino","it":"Nidorino"}',
   '{"ko":"독침포켓몬","en":"Poison Pin Pokémon","ja":"どくばりポケモン","zh-Hans":"毒针宝可梦","zh-Hant":"毒針寶可夢","fr":"Pokémon Vénépic","de":"Giftdorn-Pokémon","es":"Pokémon Pin Veneno","it":"Pokémon Velenago"}',
   '{"ko":"신경질적이고 호전적이다. 체내의 아드레날린이 증가하면 독소의 농도도 높아진다.","en":"It’s nervous and quick to act aggressively. The potency of its poison increases along with the level of adrenaline present in its body.","ja":"神経質で　喧嘩っ早い。体内の　アドレナリンが　増えると毒素の　濃度も　高まるぞ。","zh-Hans":"神经敏感，动不动就打架。体内的肾上腺素一增加，毒素的浓度也会提高。","zh-Hant":"神經質且容易發脾氣打架。當體內的腎上腺素增加時，毒素的濃度也會提升。","fr":"D’un naturel nerveux, il est prompt à se battre. Lorsqu’il a une montée d’adrénaline, la concentration de son poison augmente.","de":"Es ist nervös und wird schnell aggressiv. Steigt sein Adrenalinspiegel, erhöht sich gleichzeitig auch die Konzentration seines Gifts.","es":"Es nervioso y agresivo por naturaleza. Cuando suben sus niveles de adrenalina, la concentración de toxinas en su veneno aumenta.","it":"È irritabile e sempre pronto a battersi. Quando il livello di adrenalina nel suo corpo si alza, aumenta anche la concentrazione di tossine."}',
   'poison', null, 61, 72, 57, 55, 55, 65, 9, 195,
   'medium-slow', 120, 20, 0, false, false, false,
   13, 32, '{"trigger":"level-up","min_level":16}', '{"animated":"/sprites/pokemon/33.gif","animated_shiny":"/sprites/pokemon/shiny/33.gif"}'),
  (34, 'nidoking', 34, true, 1,
   '{"ko":"니드킹","en":"Nidoking","ja":"ニドキング","zh-Hans":"尼多王","zh-Hant":"尼多王","fr":"Nidoking","de":"Nidoking","es":"Nidoking","it":"Nidoking"}',
   '{"ko":"드릴포켓몬","en":"Drill Pokémon","ja":"ドリルポケモン","zh-Hans":"钻锥宝可梦","zh-Hant":"鑽錐寶可夢","fr":"Pokémon Perceur","de":"Bohrer-Pokémon","es":"Pokémon Taladro","it":"Pokémon Trapano"}',
   '{"ko":"힘이 센 포켓몬이다. 굵은 꼬리와 다이아몬드도 부수는 뿔로 호쾌하게 싸운다.","en":"Nidoking prides itself on its strength. It’s forceful and spirited in battle, making use of its thick tail and diamond-crushing horn.","ja":"力自慢の　ポケモン。　太い　尻尾とダイヤをも　砕く　ツノを　駆使して豪快に　戦う。","zh-Hans":"以力量为傲的宝可梦。用自己的粗尾巴和连钻石都能击碎的角，豪爽地战斗。","zh-Hant":"以力氣為傲的寶可夢。會善用粗壯的尾巴和連鑽石也能擊碎的角，豪邁地戰鬥。","fr":"Très fier de sa force, il se bat vigoureusement à l’aide de sa queue robuste et de sa corne capable de briser le diamant.","de":"Nidoking ist stolz auf seine Kraft und kämpft sehr geschickt mit seinem dicken Schweif und seinem Horn, das selbst Diamanten zertrümmern kann.","es":"Presume de su hercúlea fuerza y combate vigorosamente con su robusta cola y su cuerno, con el que hasta puede pulverizar diamantes.","it":"Si dà vanto della propria forza e lotta con vigore sfruttando la coda robusta e il corno in grado di frantumare il diamante."}',
   'poison', 'ground', 81, 102, 77, 85, 75, 85, 14, 620,
   'medium-slow', 45, 20, 0, false, false, false,
   13, 33, '{"trigger":"use-item","item":{"id":"moon-stone","names":{"ko":"달의돌","en":"Moon Stone","ja":"つきのいし","zh-Hans":"月之石","zh-Hant":"月之石","fr":"Pierre Lune","de":"Mondstein","es":"Piedra Lunar","it":"Pietralunare"}}}', '{"animated":"/sprites/pokemon/34.gif","animated_shiny":"/sprites/pokemon/shiny/34.gif"}'),
  (35, 'clefairy', 35, true, 1,
   '{"ko":"삐삐","en":"Clefairy","ja":"ピッピ","zh-Hans":"皮皮","zh-Hant":"皮皮","fr":"Mélofée","de":"Piepi","es":"Clefairy","it":"Clefairy"}',
   '{"ko":"요정포켓몬","en":"Fairy Pokémon","ja":"ようせいポケモン","zh-Hans":"妖精宝可梦","zh-Hant":"妖精寶可夢","fr":"Pokémon Fée","de":"Feen-Pokémon","es":"Pokémon Hada","it":"Pokémon Fata"}',
   '{"ko":"애교 있는 몸동작과 울음소리로 귀엽다고 많은 인기를 누리는 포켓몬. 그러나 좀처럼 눈에 띄지 않는다.","en":"It can be found in quiet mountain areas on a full moon''s night. Its dancing and its tiny, faintly glowing wings confer upon it a lovely fairylike quality.","ja":"愛くるしい　しぐさと　鳴き声でかわいいと　大人気の　ポケモン。だが　めったに　見つからない。","zh-Hans":"因可爱的举止和叫声而广受欢迎的宝可梦。不过很少被人发现。","zh-Hant":"因可愛的舉止和叫聲而廣受歡迎的寶可夢。不過很少被人發現。","fr":"Son comportement et son cri adorables font de lui un Pokémon très populaire. Malheureusement, il est difficile d’en croiser un spécimen.","de":"Aufgrund seines reizenden Wesens und seines Rufes erfreut sich dieses Pokémon großer Beliebtheit. Leider ist es auch sehr selten.","es":"Su adorable grito y comportamiento lo hacen muy popular. Sin embargo, raramente se avista.","it":"Il suo verso e le sue movenze graziose rendono questo adorabile Pokémon molto popolare. Sfortunatamente, però, è molto raro."}',
   'fairy', null, 70, 45, 48, 60, 65, 35, 6, 75,
   'fast', 150, 10, 6, false, false, false,
   14, null, null, '{"animated":"/sprites/pokemon/35.gif","animated_shiny":"/sprites/pokemon/shiny/35.gif"}'),
  (36, 'clefable', 36, true, 1,
   '{"ko":"픽시","en":"Clefable","ja":"ピクシー","zh-Hans":"皮可西","zh-Hant":"皮可西","fr":"Mélodelfe","de":"Pixi","es":"Clefable","it":"Clefable"}',
   '{"ko":"요정포켓몬","en":"Fairy Pokémon","ja":"ようせいポケモン","zh-Hans":"妖精宝可梦","zh-Hant":"妖精寶可夢","fr":"Pokémon Fée","de":"Feen-Pokémon","es":"Pokémon Hada","it":"Pokémon Fata"}',
   '{"ko":"1km 앞에 떨어진 바늘 소리가 들릴 정도로 귀가 좋아 평소에는 조용한 곳에서 지낸다.","en":"Legend says that on clear, quiet nights, it listens for the voices of its kin living on the moon. I, too, often think of my homeland, so far away.","ja":"１キロ先に　落ちた　針の　音も聞こえるほど　耳が　いいのでふだんは　静かな　ところに　いる。","zh-Hans":"听觉灵敏，连１公里以外针落地的声音都听得见，因此平时会待在安静的地方。","zh-Hant":"聽覺靈敏，連１公里以外針落地的聲音都聽得見，因此平時會待在安靜的地方。","fr":"Capable d’entendre une aiguille tomber à plus d’un kilomètre, ce Pokémon préfère les endroits calmes et isolés.","de":"Ihr Gehör erfasst das Geräusch einer fallenden Nadel noch aus 1 km Entfernung. Sie bevorzugen daher ruhige Orte.","es":"Su oído es tan fino que puede percibir cómo cae una aguja a 1 km de distancia. Por eso suele habitar en lugares tranquilos.","it":"Il loro udito è così acuto che sentono un ago cadere a 1 km di distanza. Per questo di solito vivono in luoghi molto silenziosi."}',
   'fairy', null, 95, 70, 73, 95, 90, 60, 13, 400,
   'fast', 25, 10, 6, false, false, false,
   14, 35, '{"trigger":"use-item","item":{"id":"moon-stone","names":{"ko":"달의돌","en":"Moon Stone","ja":"つきのいし","zh-Hans":"月之石","zh-Hant":"月之石","fr":"Pierre Lune","de":"Mondstein","es":"Piedra Lunar","it":"Pietralunare"}}}', '{"animated":"/sprites/pokemon/36.gif","animated_shiny":"/sprites/pokemon/shiny/36.gif"}'),
  (37, 'vulpix', 37, true, 1,
   '{"ko":"식스테일","en":"Vulpix","ja":"ロコン","zh-Hans":"六尾","zh-Hant":"六尾","fr":"Goupix","de":"Vulpix","es":"Vulpix","it":"Vulpix"}',
   '{"ko":"여우포켓몬","en":"Fox Pokémon","ja":"きつねポケモン","zh-Hans":"狐狸宝可梦","zh-Hant":"狐狸寶可夢","fr":"Pokémon Renard","de":"Fuchs-Pokémon","es":"Pokémon Zorro","it":"Pokémon Volpe"}',
   '{"ko":"6개의 꼬리는 자라면서 털의 결이 좋아지며 아름다워진다. 안으면 살짝 따듯하다.","en":"In its belly burns a fire, which Vulpix spits out in the form of fireballs. When young, this Pokémon has but one white tail. As the Pokémon matures, this single tail splits into six.","ja":"６本の　しっぽは　育つごとに毛並みが　良くなり　美しくなる。抱きしめると　ほんのり　温かい。","zh-Hans":"随着身体的成长，６根尾巴的毛发也会变得更漂亮。紧紧抱着它时能感到微微的温暖。","zh-Hant":"隨著身體的成長，６根尾巴的毛髮也會變得更漂亮。緊緊抱著牠時能感到微微的溫暖。","fr":"Avec l’âge, la fourrure de ses six queues devient de plus en plus belle et soyeuse. Elle est chaude au toucher.","de":"Sein Fell wird geschmeidiger, wenn seine sechs Schweife wachsen. Wenn man das Fell berührt, fühlt es sich leicht warm an.","es":"Su pelaje se va volviendo más suave, lustroso y bello a medida que le crecen las seis colas. Al abrazarlo, emana una ligera calidez.","it":"Man mano che cresce, le sue sei code diventano sempre più belle. La pelliccia di cui sono ricoperte è calda al tatto."}',
   'fire', null, 38, 41, 40, 50, 65, 65, 6, 99,
   'medium', 190, 20, 6, false, false, false,
   15, null, null, '{"animated":"/sprites/pokemon/37.gif","animated_shiny":"/sprites/pokemon/shiny/37.gif"}'),
  (38, 'ninetales', 38, true, 1,
   '{"ko":"나인테일","en":"Ninetales","ja":"キュウコン","zh-Hans":"九尾","zh-Hant":"九尾","fr":"Feunard","de":"Vulnona","es":"Ninetales","it":"Ninetales"}',
   '{"ko":"여우포켓몬","en":"Fox Pokémon","ja":"きつねポケモン","zh-Hans":"狐狸宝可梦","zh-Hant":"狐狸寶可夢","fr":"Pokémon Renard","de":"Fuchs-Pokémon","es":"Pokémon Zorro","it":"Pokémon Volpe"}',
   '{"ko":"머리가 좋고 집념이 강하다. 장난으로 꼬리를 잡으면 1000년 동안 화를 입는다고 한다.","en":"The coat of gleaming golden fur is quite magnificent. This species is said to store sacred power in its nine long tails and to live for a millennium.","ja":"頭が良くて　執念深い。ふざけて　しっぽを　つかむと１０００年　たたられるという。","zh-Hans":"聪明伶俐，但爱记仇。据说如果敢乱抓它的尾巴，它就会缠着你作祟１０００年。","zh-Hant":"聰明伶俐但很會記仇。據說如果敢亂抓牠的尾巴，牠就會纏著你作祟１０００年。","fr":"Il est très intelligent et rancunier. Quiconque attrape une de ses queues se fera maudire pour 1 000 ans.","de":"Dieses Pokémon ist intelligent, aber rachsüchtig. Wer zum Spaß einen seiner Schweife ergreift, kann sich einen tausendjährigen Fluch einhandeln.","es":"Muy inteligente y vengativo. Agarrar una de sus colas podría traer 1000 años de mala suerte.","it":"Molto intelligente e vendicativo. Chi gli afferra una coda rischia una maledizione millenaria."}',
   'fire', null, 73, 76, 75, 81, 100, 100, 11, 199,
   'medium', 75, 20, 6, false, false, false,
   15, 37, '{"trigger":"use-item","item":{"id":"fire-stone","names":{"ko":"불꽃의돌","en":"Fire Stone","ja":"ほのおのいし","zh-Hans":"火之石","zh-Hant":"火之石","fr":"Pierre Feu","de":"Feuerstein","es":"Piedra Fuego","it":"Pietrafocaia"}}}', '{"animated":"/sprites/pokemon/38.gif","animated_shiny":"/sprites/pokemon/shiny/38.gif"}'),
  (39, 'jigglypuff', 39, true, 1,
   '{"ko":"푸린","en":"Jigglypuff","ja":"プリン","zh-Hans":"胖丁","zh-Hant":"胖丁","fr":"Rondoudou","de":"Pummeluff","es":"Jigglypuff","it":"Jigglypuff"}',
   '{"ko":"풍선포켓몬","en":"Balloon Pokémon","ja":"ふうせんポケモン","zh-Hans":"气球宝可梦","zh-Hant":"氣球寶可夢","fr":"Pokémon Bouboule","de":"Ballon-Pokémon","es":"Pokémon Globo","it":"Pokémon Pallone"}',
   '{"ko":"목소리 파장을 자유자재로 바꾸어 들으면 반드시 잠드는 신비한 멜로디를 노래한다.","en":"By freely changing the wavelength of its voice, Jigglypuff sings a mysterious melody sure to make any listener sleepy.","ja":"声の　波長を　自在に　変えて聞くと　絶対に　眠くなる不思議な　メロディーを　歌う。","zh-Hans":"能够随意改变声音的波长，唱出听了绝对会犯困的神奇旋律。","zh-Hant":"會自在地改變聲音的波長，唱出一聽見就絕對會昏昏欲睡的神奇旋律。","fr":"Il module librement la longueur d’onde de sa voix pour chanter une étrange mélodie qui endort à tous les coups celui qui l’écoute.","de":"Es kann die Tonlage seiner Stimme beliebig variieren, um eine mysteriöse Melodie zu singen, die jeden in Schlaf versetzt, der sie hört.","es":"Posee la capacidad de modular su voz a voluntad cambiando la longitud de onda para entonar una melodía misteriosa que provoca adormecimiento.","it":"Modulando a piacere la lunghezza d’onda della sua voce, canta una melodia misteriosa che fa addormentare immancabilmente chi la ascolta."}',
   'normal', 'fairy', 115, 45, 20, 45, 25, 20, 5, 55,
   'fast', 170, 10, 6, false, false, false,
   16, null, null, '{"animated":"/sprites/pokemon/39.gif","animated_shiny":"/sprites/pokemon/shiny/39.gif"}'),
  (40, 'wigglytuff', 40, true, 1,
   '{"ko":"푸크린","en":"Wigglytuff","ja":"プクリン","zh-Hans":"胖可丁","zh-Hant":"胖可丁","fr":"Grodoudou","de":"Knuddeluff","es":"Wigglytuff","it":"Wigglytuff"}',
   '{"ko":"풍선포켓몬","en":"Balloon Pokémon","ja":"ふうせんポケモン","zh-Hans":"气球宝可梦","zh-Hant":"氣球寶可夢","fr":"Pokémon Bouboule","de":"Ballon-Pokémon","es":"Pokémon Globo","it":"Pokémon Pallone"}',
   '{"ko":"얇고 고운 털을 가졌다. 특히 이마에 동그랗게 말린 털은 하늘을 날 듯한 최고의 감촉을 지녔다.","en":"It’s proud of its fur, which is fine and delicate. In particular, the curl on its forehead has a texture that’s perfectly heavenly.","ja":"きめ細やかな　体毛が　自慢。とくに　額の　巻き毛は天にも　昇る　極上の　手触り。","zh-Hans":"以自己细腻的体毛为傲。尤其是额头上的卷毛，更是有着天堂般的极致触感。","zh-Hant":"以自己細緻的體毛為傲。尤其額頭上的捲毛，更是有著彷彿會一摸升天的極致觸感。","fr":"Sa fourrure soyeuse fait sa fierté. La touffe sur son front est si douce que la caresser donne l’impression d’être sur un petit nuage.","de":"Knuddeluffs weiches Fell ist sein ganzer Stolz. Besonders die Locke auf seiner Stirn fühlt sich herrlich an.","es":"Se enorgullece de su pelaje fino y sedoso. El rizo de la frente, en especial, posee un tacto sublime.","it":"Va molto fiero del suo manto soffice. Il ricciolo sulla fronte, in particolare, suscita una sensazione sublime al tatto."}',
   'normal', 'fairy', 140, 70, 45, 85, 50, 45, 10, 120,
   'fast', 50, 10, 6, false, false, false,
   16, 39, '{"trigger":"use-item","item":{"id":"moon-stone","names":{"ko":"달의돌","en":"Moon Stone","ja":"つきのいし","zh-Hans":"月之石","zh-Hant":"月之石","fr":"Pierre Lune","de":"Mondstein","es":"Piedra Lunar","it":"Pietralunare"}}}', '{"animated":"/sprites/pokemon/40.gif","animated_shiny":"/sprites/pokemon/shiny/40.gif"}'),
  (41, 'zubat', 41, true, 1,
   '{"ko":"주뱃","en":"Zubat","ja":"ズバット","zh-Hans":"超音蝠","zh-Hant":"超音蝠","fr":"Nosferapti","de":"Zubat","es":"Zubat","it":"Zubat"}',
   '{"ko":"박쥐포켓몬","en":"Bat Pokémon","ja":"こうもりポケモン","zh-Hans":"蝙蝠宝可梦","zh-Hant":"蝙蝠寶可夢","fr":"Pokémon Chovsouris","de":"Fledermaus-Pokémon","es":"Pokémon Murciélago","it":"Pokémon Pipistrello"}',
   '{"ko":"볕이 들지 않는 동굴에 산다. 아침이 되면 동료들끼리 모여 서로의 온기를 나누면서 잔다.","en":"Makes its home in gloomy caves. Atrophied eyes have left this Pokémon blind, so it scans its surroundings via sound waves that it emits from its mouth as it flies.","ja":"陽の　当たらない　洞窟に　棲む。朝になると　仲間で　集まり体を　温めあいながら　寝る。","zh-Hans":"栖息在晒不到阳光的洞窟里。到了早晨便会和同伴聚集起来，一边互相取暖一边睡觉。","zh-Hant":"棲息在陽光照射不到的洞窟裡。到了早上就會和夥伴相聚，一邊互相取暖一邊睡覺。","fr":"Ils vivent dans les grottes où la lumière du jour ne perce jamais. Le matin, ils se blottissent les uns contre les autres pour se réchauffer et dormir.","de":"Zubat leben tief in Höhlen, wo das Sonnenlicht sie nicht erreicht. Bei Tagesanbruch rücken sie zusammen, um sich im Schlaf zu wärmen.","es":"Habitan en cuevas donde no llegan los rayos del sol. De día, se acurrucan unos junto a otros para entrar en calor mientras duermen.","it":"Vive in grotte mai rischiarate dalla luce del sole. Quando si fa giorno, si raggruppa con i suoi simili per scaldarsi mentre dorme."}',
   'poison', 'flying', 40, 45, 35, 30, 40, 55, 8, 75,
   'medium', 255, 15, 4, false, false, false,
   17, null, null, '{"animated":"/sprites/pokemon/41.gif","animated_shiny":"/sprites/pokemon/shiny/41.gif"}'),
  (42, 'golbat', 42, true, 1,
   '{"ko":"골뱃","en":"Golbat","ja":"ゴルバット","zh-Hans":"大嘴蝠","zh-Hant":"大嘴蝠","fr":"Nosferalto","de":"Golbat","es":"Golbat","it":"Golbat"}',
   '{"ko":"박쥐포켓몬","en":"Bat Pokémon","ja":"こうもりポケモン","zh-Hans":"蝙蝠宝可梦","zh-Hant":"蝙蝠寶可夢","fr":"Pokémon Chovsouris","de":"Fledermaus-Pokémon","es":"Pokémon Murciélago","it":"Pokémon Pipistrello"}',
   '{"ko":"작은 다리로 능숙하게 걷는다. 자고 있는 먹이에게 살며시 다가가 이빨을 꽂아 피를 빨아먹는다.","en":"It sinks its sharp fangs into other creatures and slurps up their blood. A closer look at the fangs reveals that they are hollow and akin to straws.","ja":"小さな　脚で　器用に　歩く。寝ている　獲物に　忍びよりキバを　突きたて　血を　すするのだ。","zh-Hans":"用小而灵活的脚走路。会悄悄接近正在睡觉的猎物，用尖牙咬住对方吸取血液。","zh-Hant":"能以小小的腳靈巧地步行。會無聲無息地靠近沉睡中的獵物，用獠牙咬住對方並且吸食血液。","fr":"Il se déplace habilement sur ses petites pattes, s’approche silencieusement de sa proie endormie, et lui suce le sang à l’aide de ses crocs.","de":"Golbat kann trotz seiner kleinen Beine geschickt laufen. Es schleicht sich an schlafende Beute an, stößt seine Zähne in sie und schlürft ihr Blut.","es":"Camina con soltura sobre sus pequeñas patas. Se acerca con sigilo a su presa mientras esta duerme y le clava los colmillos para chuparle la sangre.","it":"Cammina agilmente con i piccoli piedi. Si avvicina di soppiatto alle prede addormentate per azzannarle e berne il sangue."}',
   'poison', 'flying', 75, 80, 70, 65, 75, 90, 16, 550,
   'medium', 90, 15, 4, false, false, false,
   17, 41, '{"trigger":"level-up","min_level":22}', '{"animated":"/sprites/pokemon/42.gif","animated_shiny":"/sprites/pokemon/shiny/42.gif"}'),
  (43, 'oddish', 43, true, 1,
   '{"ko":"뚜벅쵸","en":"Oddish","ja":"ナゾノクサ","zh-Hans":"走路草","zh-Hant":"走路草","fr":"Mystherbe","de":"Myrapla","es":"Oddish","it":"Oddish"}',
   '{"ko":"잡초포켓몬","en":"Weed Pokémon","ja":"ざっそうポケモン","zh-Hans":"杂草宝可梦","zh-Hant":"雜草寶可夢","fr":"Pokémon Racine","de":"Unkraut-Pokémon","es":"Pokémon Hierbajo","it":"Pokémon Malerba"}',
   '{"ko":"낮에는 태양을 피하기 위해 차가운 땅속에 들어가 있다. 달빛을 쬐어 성장한다.","en":"During the day, it stays in the cold underground to avoid the sun. It grows by bathing in moonlight.","ja":"昼間は　太陽を　避けるため冷たい　地面に　もぐっている。月の光を　浴びて　育つ。","zh-Hans":"白天会为躲避太阳而钻入凉爽的地下。会通过沐浴月光成长。","zh-Hant":"白天為了躲避太陽，會鑽進涼爽的地下。藉由沐浴月光來成長。","fr":"Pendant la journée, il reste en sous-sol et évite le soleil. Il grandit en se baignant au clair de lune.","de":"Tagsüber versteckt es sich in der kalten Erde, um die Sonne zu meiden. Es wächst im Mondschein.","es":"Durante el día, se agazapa en el frío subsuelo huyendo del sol. La luz de la luna le hace crecer.","it":"Di giorno vive nel freddo sottosuolo per evitare la luce del sole. Cresce assorbendo la luce lunare."}',
   'grass', 'poison', 45, 50, 55, 75, 65, 30, 5, 54,
   'medium-slow', 255, 20, 4, false, false, false,
   18, null, null, '{"animated":"/sprites/pokemon/43.gif","animated_shiny":"/sprites/pokemon/shiny/43.gif"}'),
  (44, 'gloom', 44, true, 1,
   '{"ko":"냄새꼬","en":"Gloom","ja":"クサイハナ","zh-Hans":"臭臭花","zh-Hant":"臭臭花","fr":"Ortide","de":"Duflor","es":"Gloom","it":"Gloom"}',
   '{"ko":"잡초포켓몬","en":"Weed Pokémon","ja":"ざっそうポケモン","zh-Hans":"杂草宝可梦","zh-Hant":"雜草寶可夢","fr":"Pokémon Racine","de":"Unkraut-Pokémon","es":"Pokémon Hierbajo","it":"Pokémon Malerba"}',
   '{"ko":"침처럼 보이는 달콤한 꿀은 매우 끈적거려서 묻으면 좀처럼 떨어지지 않는다.","en":"What appears to be drool is actually sweet honey. It is very sticky and clings stubbornly if touched.","ja":"よだれのように　見える　甘い蜜。とても　ねばねば　しており　触れるといつまでも　まとわりつく。","zh-Hans":"看似口水的东西其实是甜甜的蜜。非常黏稠，只要碰到就会一直黏住。","zh-Hant":"看似口水的東西其實是甜甜的蜜。非常黏稠，只要碰到就會一直黏住。","fr":"Ce qui semble être sa bave est en fait du nectar très collant. Si on le touche, il est très difficile de s’en dépêtrer.","de":"Was wie Speichel aussieht, ist eigentlich Honig. Er ist sehr klebrig und wenn man ihn berührt, bekommt man ihn nicht mehr ab.","es":"Lo que parece baba es realmente un néctar muy pegajoso que se adhiere sin remisión al tocarlo.","it":"Ciò che sembra bava è in realtà dolce nettare. È molto viscoso: si appiccica appena lo si sfiora."}',
   'grass', 'poison', 60, 65, 70, 85, 75, 40, 8, 86,
   'medium-slow', 120, 20, 4, false, false, false,
   18, 43, '{"trigger":"level-up","min_level":21}', '{"animated":"/sprites/pokemon/44.gif","animated_shiny":"/sprites/pokemon/shiny/44.gif"}'),
  (45, 'vileplume', 45, true, 1,
   '{"ko":"라플레시아","en":"Vileplume","ja":"ラフレシア","zh-Hans":"霸王花","zh-Hant":"霸王花","fr":"Rafflesia","de":"Giflor","es":"Vileplume","it":"Vileplume"}',
   '{"ko":"꽃포켓몬","en":"Flower Pokémon","ja":"フラワーポケモン","zh-Hans":"花宝可梦","zh-Hant":"花寶可夢","fr":"Pokémon Fleur","de":"Blumen-Pokémon","es":"Pokémon Flor","it":"Pokémon Fiore"}',
   '{"ko":"꽃잎이 클수록 많은 꽃가루를 만들어 내지만 머리가 무거워서 지쳐버린다고 한다.","en":"The larger its petals, the more toxic pollen it contains. Its big head is heavy and hard to hold up.","ja":"花びらが　大きいほどたくさん　花粉を　出すが頭が　重たくて　疲れてしまうという。","zh-Hans":"虽然花瓣越大，就能放出越多的花粉，但这样脑袋会变沉，容易疲倦。","zh-Hant":"雖然花瓣越大就能放出越多的花粉，但頭部也會隨之變重而容易疲倦。","fr":"Plus ses pétales sont grands, plus il produit de pollen toxique. Toutefois, le poids de sa tête le fatigue.","de":"Je größer die Blütenblätter, desto mehr giftige Pollen enthält die Blüte. Aber es ist auch umso erschöpfter, da sein Kopf so schwer wird.","es":"Cuanto mayores son sus pétalos, más tóxico es su polen. Le pesa la cabeza y le cuesta mantenerla erguida.","it":"Più grandi sono i petali, maggiore è la quantità di polline tossico che contengono. La testa, però, diventa molto pesante e fa fatica a sostenerla."}',
   'grass', 'poison', 75, 80, 85, 110, 90, 50, 12, 186,
   'medium-slow', 45, 20, 4, false, false, false,
   18, 44, '{"trigger":"use-item","item":{"id":"leaf-stone","names":{"ko":"리프의돌","en":"Leaf Stone","ja":"リーフのいし","zh-Hans":"叶之石","zh-Hant":"葉之石","fr":"Pierre Plante","de":"Blattstein","es":"Piedra Hoja","it":"Pietrafoglia"}}}', '{"animated":"/sprites/pokemon/45.gif","animated_shiny":"/sprites/pokemon/shiny/45.gif"}'),
  (46, 'paras', 46, true, 1,
   '{"ko":"파라스","en":"Paras","ja":"パラス","zh-Hans":"派拉斯","zh-Hant":"派拉斯","fr":"Paras","de":"Paras","es":"Paras","it":"Paras"}',
   '{"ko":"버섯포켓몬","en":"Mushroom Pokémon","ja":"きのこポケモン","zh-Hans":"蘑菇宝可梦","zh-Hant":"蘑菇寶可夢","fr":"Pokémon Champignon","de":"Pilz","es":"Pokémon Hongo","it":"Pokémon Fungo"}',
   '{"ko":"구멍을 파서 나무뿌리로부터 영양을 섭취하지만 대부분은 등에 있는 버섯에게 빼앗긴다.","en":"Sometimes seen at the foot of trees in humid forests. The mushrooms on its back—called tochukaso—are not present on infant specimens and instead emerge as Paras matures.","ja":"穴を掘り　木の根っこ　から栄養を　摂るが　ほとんどは背中の　キノコに　奪われる。","zh-Hans":"它会通过挖洞来从树根里吸取营养，但大部分营养都会被背上的蘑菇抢走。","zh-Hant":"會挖掘洞穴，從樹木的根部獲取營養，但幾乎所有的營養都會被背上的蘑菇奪走。","fr":"Il s’enfouit pour ronger des racines, mais ce sont les champignons sur son dos qui absorbent presque tous les nutriments.","de":"Es gräbt sich in den Boden, um Baumwurzeln Nährstoffe zu entziehen. Den Großteil davon absorbieren jedoch die Pilze auf seinem Rücken.","es":"Escarba en el suelo para extraer nutrientes de las raíces de los árboles, que las setas del lomo absorben después casi por completo.","it":"Scava nella terra per cibarsi delle radici degli alberi, ma i funghi che ha sul dorso assorbono quasi tutte le sostanze nutritive."}',
   'bug', 'grass', 35, 70, 55, 45, 55, 25, 3, 54,
   'medium', 190, 20, 4, false, false, false,
   19, null, null, '{"animated":"/sprites/pokemon/46.gif","animated_shiny":"/sprites/pokemon/shiny/46.gif"}'),
  (47, 'parasect', 47, true, 1,
   '{"ko":"파라섹트","en":"Parasect","ja":"パラセクト","zh-Hans":"派拉斯特","zh-Hant":"派拉斯特","fr":"Parasect","de":"Parasek","es":"Parasect","it":"Parasect"}',
   '{"ko":"버섯포켓몬","en":"Mushroom Pokémon","ja":"きのこポケモン","zh-Hans":"蘑菇宝可梦","zh-Hant":"蘑菇寶可夢","fr":"Pokémon Champignon","de":"Pilz","es":"Pokémon Hongo","it":"Pokémon Fungo"}',
   '{"ko":"계속 진액을 빨아 먹혀서 이제는 벌레가 아니라 등에 있는 버섯이 생각하고 있는 듯하다.","en":"Mushroom-lacking specimens of this Pokémon lie unmoving in the forest, lending credence to the hypothesis that the large mushroom is in control of Parasect''s actions.","ja":"ずっと　エキスを　吸い続けられもはや　ムシではなく　背中のキノコが　考えているようだ。","zh-Hans":"由于虫子的精华不断被吸走，在思考的似乎已经不是虫子，而是背上的蘑菇了。","zh-Hant":"由於蟲子的精華不斷被吸走，在思考的似乎已經不是蟲子，而是背上的蘑菇了。","fr":"À force de voir son énergie aspirée, il semblerait que ce ne soit plus l’insecte qui réfléchisse, mais le champignon sur son dos.","de":"Der Pilz auf Paraseks Rücken nutzt das Pokémon als Wirt und entzieht ihm Energie. Es scheint, als habe er die Kontrolle über das Pokémon.","es":"Tras largo tiempo absorbiendo la energía del huésped, la seta parásita del lomo es la que parece controlar la voluntad de este Pokémon.","it":"Il fungo sulla schiena assorbe l’energia dell’organismo ospite, su cui ha anche pieno controllo."}',
   'bug', 'grass', 60, 95, 80, 60, 80, 30, 10, 295,
   'medium', 75, 20, 4, false, false, false,
   19, 46, '{"trigger":"level-up","min_level":24}', '{"animated":"/sprites/pokemon/47.gif","animated_shiny":"/sprites/pokemon/shiny/47.gif"}'),
  (48, 'venonat', 48, true, 1,
   '{"ko":"콘팡","en":"Venonat","ja":"コンパン","zh-Hans":"毛球","zh-Hant":"毛球","fr":"Mimitoss","de":"Bluzuk","es":"Venonat","it":"Venonat"}',
   '{"ko":"곤충포켓몬","en":"Insect Pokémon","ja":"こんちゅうポケモン","zh-Hans":"昆虫宝可梦","zh-Hant":"昆蟲寶可夢","fr":"Pokémon Vermine","de":"Insekt","es":"Pokémon Insecto","it":"Pokémon Insetto"}',
   '{"ko":"레이더 역할을 하는 큰 눈은 밝은 곳에서 보면 작은 눈이 모여서 이루어진 것임을 알 수 있다.","en":"Its large eyes act as radar. In a bright place, you can see that they are clusters of many tiny eyes.","ja":"レーダーになる　大きな　目は明るいところでは　小さな　目が集まって　できているのが　わかる。","zh-Hans":"在明亮的地方你便能发现它具有雷达功能的大眼其实是由许多个小眼睛聚集而成的。","zh-Hant":"在明亮的地方看就會發現那對有著雷達作用的大眼睛，是由許多小眼睛聚集而成的。","fr":"Ses grands yeux lui servent de radar. En pleine lumière, on peut y distinguer des facettes.","de":"Seine großen Augen fungieren als Radar. Im Licht kann man erkennen, dass sie aus unzähligen, sehr kleinen Augen bestehen.","es":"Sus grandes ojos actúan como radares. A plena luz se percibe que son, en realidad, grupos de ojos diminutos.","it":"Gli occhi enormi fungono da radar. Alla luce si può notare che sono formati da molti occhi più piccoli."}',
   'bug', 'poison', 60, 55, 50, 40, 55, 45, 10, 300,
   'medium', 190, 20, 4, false, false, false,
   20, null, null, '{"animated":"/sprites/pokemon/48.gif","animated_shiny":"/sprites/pokemon/shiny/48.gif"}'),
  (49, 'venomoth', 49, true, 1,
   '{"ko":"도나리","en":"Venomoth","ja":"モルフォン","zh-Hans":"摩鲁蛾","zh-Hant":"摩魯蛾","fr":"Aéromite","de":"Omot","es":"Venomoth","it":"Venomoth"}',
   '{"ko":"독나방포켓몬","en":"Poison Moth Pokémon","ja":"どくがポケモン","zh-Hans":"毒蛾宝可梦","zh-Hant":"毒蛾寶可夢","fr":"Pokémon Papipoison","de":"Giftmotte","es":"Pokémon Polilla Ven.","it":"Pokémon Velentarma"}',
   '{"ko":"날개의 인분은 몸에 묻으면 좀처럼 떨어지지 않는다. 게다가 거기에서 독성분이 스며든다.","en":"The powdery scales on its wings are hard to remove from skin. They also contain poison that leaks out on contact.","ja":"ハネの　りん粉は　体につくとなかなか　取れない。しかも　そこから毒の　成分が　染み込んでくる。","zh-Hans":"如果不小心把它翅膀上的鳞粉沾到了身上，那不但会很难去除，更糟的是毒素也会从那里渗入。","zh-Hant":"翅膀上的鱗粉一旦沾到身上就很難甩掉，而且鱗粉帶有的毒素還會逐漸滲入體內。","fr":"Les écailles de ses ailes sont presque impossibles à retirer lorsqu’elles se collent à la peau, et elles libèrent un poison violent au contact.","de":"Berührt man die staubartigen Schuppen auf seinen Flügeln, heften diese sich hartnäckig am Körper an und sondern darüber hinaus Gift ab.","es":"Las alas desprenden un polvillo de escamas impregnado de toxinas que se adhiere al contacto y resulta difícil de quitar.","it":"Se si attaccano alla pelle, le scaglie che ricoprono le sue ali sono difficili da togliere. Inoltre, rilasciano una sostanza velenosa."}',
   'bug', 'poison', 70, 65, 60, 90, 75, 90, 15, 125,
   'medium', 75, 20, 4, false, false, false,
   20, 48, '{"trigger":"level-up","min_level":31}', '{"animated":"/sprites/pokemon/49.gif","animated_shiny":"/sprites/pokemon/shiny/49.gif"}'),
  (50, 'diglett', 50, true, 1,
   '{"ko":"디그다","en":"Diglett","ja":"ディグダ","zh-Hans":"地鼠","zh-Hant":"地鼠","fr":"Taupiqueur","de":"Digda","es":"Diglett","it":"Diglett"}',
   '{"ko":"두더지포켓몬","en":"Mole Pokémon","ja":"もぐらポケモン","zh-Hans":"鼹鼠宝可梦","zh-Hant":"鼴鼠寶可夢","fr":"Pokémon Taupe","de":"Maulwurf-Pokémon","es":"Pokémon Topo","it":"Pokémon Talpa"}',
   '{"ko":"얕은 땅속을 이동한다. 굴을 파며 다닌 곳은 지면이 솟아 있기 때문에 바로 알 수 있다.","en":"It burrows through the ground at a shallow depth. It leaves raised earth in its wake, making it easy to spot.","ja":"地中の　浅いところを　移動。掘り進んだあとは　地面が盛り上がっているので　すぐわかる。","zh-Hans":"在地下较浅的地方移动。被它挖掘过的地面会鼓起来，所以非常容易发现。","zh-Hant":"在地下較淺的地方移動。被牠挖掘過的地面會鼓起來，所以非常容易發現。","fr":"Ce Pokémon creuse sous terre à faible profondeur. La terre qu’il laisse dans son sillage le rend facile à repérer.","de":"Es gräbt sich in geringer Tiefe durch den Erdboden. Da es dabei durchwühlte Erde an der Oberfläche hinterlässt, ist es leicht zu finden.","es":"Este Pokémon avanza horadando la tierra a poca profundidad. Resulta fácil localizarlo por los montículos que deja como rastro.","it":"Scava buche a bassa profondità. La terra sollevata che lascia al suo passaggio lo rende facilmente individuabile."}',
   'ground', null, 10, 55, 25, 35, 45, 95, 2, 8,
   'medium', 255, 20, 4, false, false, false,
   21, null, null, '{"animated":"/sprites/pokemon/50.gif","animated_shiny":"/sprites/pokemon/shiny/50.gif"}'),
  (51, 'dugtrio', 51, true, 1,
   '{"ko":"닥트리오","en":"Dugtrio","ja":"ダグトリオ","zh-Hans":"三地鼠","zh-Hant":"三地鼠","fr":"Triopikeur","de":"Digdri","es":"Dugtrio","it":"Dugtrio"}',
   '{"ko":"두더지포켓몬","en":"Mole Pokémon","ja":"もぐらポケモン","zh-Hans":"鼹鼠宝可梦","zh-Hant":"鼴鼠寶可夢","fr":"Pokémon Taupe","de":"Maulwurf-Pokémon","es":"Pokémon Topo","it":"Pokémon Talpa"}',
   '{"ko":"지하 100km까지 파고들 수 있는 파워를 간직한 세쌍둥이 디그다. 땅 밑은 아무도 모른다.","en":"These Diglett triplets dig over 60 miles below sea level. No one knows what it’s like underground.","ja":"地下１００キロまで　掘り進む。パワーを秘めた　三つ子の　ディグダ。地面の下は　だれも　知らない。","zh-Hans":"三胞胎的地鼠，拥有能够挖掘到地下１００公里深的潜力。没人知道它在地下的部分究竟长成什么样子。","zh-Hant":"三胞胎的地鼠，擁有能夠挖掘到地下１００公里深的潛力。沒人知道牠在地下的部分究竟長成什麼樣子。","fr":"Ce trio de Taupiqueur est capable de creuser jusqu’à 100 km sous terre, vers l’inconnu.","de":"Diese kraftvollen Digda-Drillinge graben bis zu 100 km tief. Keiner weiß, wie sie unter der Erde aussehen.","es":"Estos trillizos cavan a una profundidad de hasta 100 km. Se desconoce el aspecto de la parte de sus cuerpos que se oculta bajo tierra.","it":"Questo trio di Diglett può scavare fino a 100 km di profondità. Nessuno ha mai visto la parte nascosta sotto terra."}',
   'ground', null, 35, 100, 50, 50, 70, 120, 7, 333,
   'medium', 50, 20, 4, false, false, false,
   21, 50, '{"trigger":"level-up","min_level":26}', '{"animated":"/sprites/pokemon/51.gif","animated_shiny":"/sprites/pokemon/shiny/51.gif"}'),
  (52, 'meowth', 52, true, 1,
   '{"ko":"나옹","en":"Meowth","ja":"ニャース","zh-Hans":"喵喵","zh-Hant":"喵喵","fr":"Miaouss","de":"Mauzi","es":"Meowth","it":"Meowth"}',
   '{"ko":"요괴고양이포켓몬","en":"Scratch Cat Pokémon","ja":"ばけねこポケモン","zh-Hans":"妖怪猫宝可梦","zh-Hant":"妖怪貓寶可夢","fr":"Pokémon Chadégout","de":"Katzen-Pokémon","es":"Pokémon Gato Araña","it":"Pokémon Graffimiao"}',
   '{"ko":"이마의 금화가 더러워지지 않도록 바지런히 얼굴을 씻는다. 가라르의 나옹과는 사이가 나쁘다.","en":"It washes its face regularly to keep the coin on its forehead spotless. It doesn’t get along with Galarian Meowth.","ja":"額の　小判が　汚れないようまめに　顔を　洗う。　ガラルのニャースとは　仲が　悪い。","zh-Hans":"为了不弄脏额头上的金币，会常常洗脸。和伽勒尔的喵喵关系不好。","zh-Hant":"為了不弄髒額頭上的金幣，會常常洗臉。和伽勒爾的喵喵關係不好。","fr":"Tatillon sur la propreté de la pièce sur son front, il se lave la figure avec grand soin. Il ne s’entend pas avec les Miaouss de Galar.","de":"Es wäscht sich regelmäßig das Gesicht, um die Münze auf seiner Stirn sauber zu halten. Es hat kein gutes Verhältnis zu den Mauzi aus Galar.","es":"Se lava cuidadosamente la cara para que no se le ensucie la moneda de oro que tiene en la frente. No se lleva nada bien con los Meowth de Galar.","it":"Si lava regolarmente il muso per tenere pulita la moneta sulla fronte. Non va d’accordo con il Meowth di Galar."}',
   'normal', null, 40, 45, 35, 40, 40, 90, 4, 42,
   'medium', 255, 20, 4, false, false, false,
   22, null, null, '{"animated":"/sprites/pokemon/52.gif","animated_shiny":"/sprites/pokemon/shiny/52.gif"}'),
  (53, 'persian', 53, true, 1,
   '{"ko":"페르시온","en":"Persian","ja":"ペルシアン","zh-Hans":"猫老大","zh-Hant":"貓老大","fr":"Persian","de":"Snobilikat","es":"Persian","it":"Persian"}',
   '{"ko":"샴고양이포켓몬","en":"Classy Cat Pokémon","ja":"シャムネコポケモン","zh-Hans":"暹罗猫宝可梦","zh-Hant":"暹羅貓寶可夢","fr":"Pokémon Chadeville","de":"Rassekatzen-Pokémon","es":"Pokémon Gato Fino","it":"Pokémon Nobilgatto"}',
   '{"ko":"움직임은 우아하고 품위 있다. 야만스러운 나이킹과는 잘 맞지 않아 서로를 멸시한다.","en":"Its elegant and refined behavior clashes with that of the barbaric Perrserker. The relationship between the two is one of mutual disdain.","ja":"優雅で　上品な　身のこなし。野蛮な　ニャイキングとは　そりがあわず　お互いを　見下している。","zh-Hans":"拥有优雅高贵的身姿。与野蛮的喵头目性格不合，互相看不起对方。","zh-Hant":"擁有優雅高貴的身姿。與野蠻的喵頭目個性不合，互相看不起對方。","fr":"Il se comporte avec grâce et élégance, et ne s’entend pas avec les rustres Berserkatt : les deux espèces se méprisent.","de":"Sein Auftreten ist anmutig und elegant. Es kommt mit Mauzingers grober Art nicht zurecht. Beide Arten strafen sich gegenseitig mit Verachtung.","es":"Hace gala de un porte elegante y majestuoso. No congenia con los toscos Perrserker y ambos se profesan un mutuo desprecio.","it":"Ha un portamento elegante e distinto. Non gli va a genio la rozzezza di Perrserker e i due Pokémon si disprezzano a vicenda."}',
   'normal', null, 65, 70, 60, 65, 65, 115, 10, 320,
   'medium', 90, 20, 4, false, false, false,
   22, 52, '{"trigger":"level-up","min_level":28}', '{"animated":"/sprites/pokemon/53.gif","animated_shiny":"/sprites/pokemon/shiny/53.gif"}'),
  (54, 'psyduck', 54, true, 1,
   '{"ko":"고라파덕","en":"Psyduck","ja":"コダック","zh-Hans":"可达鸭","zh-Hant":"可達鴨","fr":"Psykokwak","de":"Enton","es":"Psyduck","it":"Psyduck"}',
   '{"ko":"오리포켓몬","en":"Duck Pokémon","ja":"あひるポケモン","zh-Hans":"鸭宝可梦","zh-Hant":"鴨寶可夢","fr":"Pokémon Canard","de":"Enten-Pokémon","es":"Pokémon Pato","it":"Pokémon Papero"}',
   '{"ko":"스트레스가 쌓이면 두통이 심해진다. 강력한 염동력으로 주위를 압도한다.","en":"Suffers perpetual headaches. If the agony grows too great, Psyduck''s latent power erupts, contrary to Psyduck''s intent. Ergo, I am exploring ways to ease the pain.","ja":"ストレスが　溜まると　頭痛がエスカレート。　強力な　念力でまわりを　圧倒する。","zh-Hans":"头痛会随着压力逐渐累积而不断加剧。会用强大的念力击垮周围的一切。","zh-Hant":"頭痛會隨著壓力累積而更加劇烈。會用強大的念力壓倒周圍的一切。","fr":"Sa migraine s’intensifie à mesure que son stress monte. Il libère une force psychique puissante qui terrasse tous ceux qui l’entourent.","de":"Wenn es sehr gestresst ist, verstärken sich seine Kopfschmerzen. Mit seinen Psycho-Kräften kann es alles in der Umgebung überwältigen.","es":"Sus dolores de cabeza empeoran a medida que aumenta su nivel de estrés. Su increíble poder psíquico puede causar estragos a su alrededor.","it":"Più è stressato, più il suo mal di testa si fa intenso. Con i suoi incredibili poteri psicocinetici travolge chiunque nelle vicinanze."}',
   'water', null, 50, 52, 48, 65, 50, 55, 8, 196,
   'medium', 190, 20, 4, false, false, false,
   23, null, null, '{"animated":"/sprites/pokemon/54.gif","animated_shiny":"/sprites/pokemon/shiny/54.gif"}'),
  (55, 'golduck', 55, true, 1,
   '{"ko":"골덕","en":"Golduck","ja":"ゴルダック","zh-Hans":"哥达鸭","zh-Hant":"哥達鴨","fr":"Akwakwak","de":"Entoron","es":"Golduck","it":"Golduck"}',
   '{"ko":"오리포켓몬","en":"Duck Pokémon","ja":"あひるポケモン","zh-Hans":"鸭宝可梦","zh-Hant":"鴨寶可夢","fr":"Pokémon Canard","de":"Enten-Pokémon","es":"Pokémon Pato","it":"Pokémon Papero"}',
   '{"ko":"강을 더럽힌 사람을 물속으로 끌어들여 데려간다는 옛날이야기가 전해져 오고 있다.","en":"Its body is strong, and it has webbing on its hands and feet. Golduck can swim easily through rough seas, clawing its way through the high waves.","ja":"川を　汚した　人間を水中に　引き込み　連れ去る昔話が　残されている。","zh-Hans":"古老的故事中说，它会把污染河水的人类拖进水中带走。","zh-Hant":"民間故事裡相傳，牠會把弄髒河川的人類拖進水裡帶走。","fr":"D’après de vieilles légendes, ce Pokémon entraînait au fond de l’eau tous ceux qui osaient souiller sa rivière.","de":"Alten Legenden zufolge werden jene Menschen, die es wagen, seinen Fluss zu verschmutzen, von Entoron ins Wasser gezerrt und entführt.","es":"Cuenta una antigua leyenda que los Golduck arrastraban a quienes contaminaran sus ríos al fondo de las aguas.","it":"Secondo antichi racconti, Golduck trascina in acqua gli esseri umani che inquinano il fiume portandoli via con sé."}',
   'water', null, 80, 82, 78, 95, 80, 85, 17, 766,
   'medium', 75, 20, 4, false, false, false,
   23, 54, '{"trigger":"level-up","min_level":33}', '{"animated":"/sprites/pokemon/55.gif","animated_shiny":"/sprites/pokemon/shiny/55.gif"}'),
  (56, 'mankey', 56, true, 1,
   '{"ko":"망키","en":"Mankey","ja":"マンキー","zh-Hans":"猴怪","zh-Hant":"猴怪","fr":"Férosinge","de":"Menki","es":"Mankey","it":"Mankey"}',
   '{"ko":"돈숭이포켓몬","en":"Pig Monkey Pokémon","ja":"ぶたざるポケモン","zh-Hans":"猪猴宝可梦","zh-Hant":"豬猴寶可夢","fr":"Pokémon Porsinge","de":"Schwein/Affe","es":"Pokémon Mono Cerdo","it":"Pokémon Suinpanzé"}',
   '{"ko":"몸이 가벼워 나무 위에서 생활한다. 사소한 일로 기분이 나빠져 주변에 있는 것에 덤벼든다.","en":"An agile Pokémon that lives in trees. It angers easily and will not hesitate to attack anything.","ja":"身軽で　木の上で　生活する。ふとしたことで　機嫌が　悪くなりまわりに　いるものに　飛びかかる。","zh-Hans":"身体轻盈，在树上生活。常因鸡毛蒜皮的小事发火而飞扑到周围的东西上。","zh-Hant":"體態輕盈的牠居住在樹上。常因為一些小事而生氣，往身邊的東西飛撲過去。","fr":"Agile et rapide, ce Pokémon vit dans les arbres. Il s’énerve facilement et s’attaque à tout ce qui bouge quand il est en colère.","de":"Es ist sehr agil und lebt auf Bäumen. Aufgrund seiner hitzköpfigen Natur wird es schnell wütend, was dazu führt, dass es alles und jeden angreift.","es":"Este ágil Pokémon vive en los árboles. Se enfada con facilidad y, cuando lo hace, se abalanza contra todo lo que se encuentre a su alrededor.","it":"Un Pokémon agile che vive sugli alberi. È molto irascibile e non esita ad attaccare chiunque gli capiti a tiro."}',
   'fighting', null, 40, 80, 35, 35, 45, 70, 5, 280,
   'medium', 190, 20, 4, false, false, false,
   24, null, null, '{"animated":"/sprites/pokemon/56.gif","animated_shiny":"/sprites/pokemon/shiny/56.gif"}'),
  (57, 'primeape', 57, true, 1,
   '{"ko":"성원숭","en":"Primeape","ja":"オコリザル","zh-Hans":"火暴猴","zh-Hant":"火爆猴","fr":"Colossinge","de":"Rasaff","es":"Primeape","it":"Primeape"}',
   '{"ko":"돈숭이포켓몬","en":"Pig Monkey Pokémon","ja":"ぶたざるポケモン","zh-Hans":"猪猴宝可梦","zh-Hant":"豬猴寶可夢","fr":"Pokémon Porsinge","de":"Schwein/Affe","es":"Pokémon Mono Cerdo","it":"Pokémon Suinpanzé"}',
   '{"ko":"주위에 아무도 없을 때만은 화를 내지 않고 있다. 그러나 그 모습을 보기가 어렵다.","en":"It stops being angry only when nobody else is around. To view this moment is very difficult.","ja":"まわりに　誰も　いないときだけは怒るのを　やめている。しかしそれを見るのは　難しい。","zh-Hans":"只有在谁都不在身边的时候才不生气，但几乎没有人目击过这种情况。","zh-Hant":"只有當誰都不在身邊的時候才會停止生氣。然而要看到牠不生氣的樣子是很困難的。","fr":"Sa fureur prend fin quand il n’a plus personne à frapper. Il est difficile d’en être témoin.","de":"Es hört lediglich dann auf zu toben, wenn niemand in der Nähe ist. Diesen Anblick zu Gesicht zu bekommen, ist daher nicht einfach.","es":"Solo se calma cuando no hay nadie cerca, por lo que llegar a ver ese momento resulta verdaderamente difícil.","it":"È molto difficile vedere questo Pokémon calmo, dato che la sua furia si placa solamente quando si trova nella solitudine più assoluta."}',
   'fighting', null, 65, 105, 60, 60, 70, 95, 10, 320,
   'medium', 75, 20, 4, false, false, false,
   24, 56, '{"trigger":"level-up","min_level":28}', '{"animated":"/sprites/pokemon/57.gif","animated_shiny":"/sprites/pokemon/shiny/57.gif"}'),
  (58, 'growlithe', 58, true, 1,
   '{"ko":"가디","en":"Growlithe","ja":"ガーディ","zh-Hans":"卡蒂狗","zh-Hant":"卡蒂狗","fr":"Caninos","de":"Fukano","es":"Growlithe","it":"Growlithe"}',
   '{"ko":"강아지포켓몬","en":"Puppy Pokémon","ja":"こいぬポケモン","zh-Hans":"小狗宝可梦","zh-Hant":"小狗寶可夢","fr":"Pokémon Chiot","de":"Welpen-Pokémon","es":"Pokémon Perrito","it":"Pokémon Cagnolino"}',
   '{"ko":"충직한 성격으로 자신의 트레이너를 지키기 위해 필사적으로 상대방에게 짖어댄다.","en":"They patrol their territory in pairs. I believe the igneous rock components in the fur of this species are the result of volcanic activity in its habitat.","ja":"忠実な　性格で　親のトレーナーを　守るため　必死に相手に　吠えかかる。","zh-Hans":"性格忠诚。为了保护自己的训练家，会拼命地朝对手狂吠。","zh-Hant":"性格忠誠。為了保護自己的訓練家，會拼命地朝對手狂吠。","fr":"Très fidèle, il aboie de toutes ses forces pour protéger son Dresseur d’Origine quand un danger le guette.","de":"Es ist sehr loyal und bellt jeden Gegner furchtlos an, um seinen Trainer vor Schaden zu bewahren.","es":"Extremadamente fiel, ladrará furioso a cualquiera que suponga una amenaza para su Entrenador con tal de defenderlo.","it":"Di indole molto leale, abbaia furiosamente contro chiunque minacci di attaccare il suo Allenatore."}',
   'fire', null, 55, 70, 45, 70, 50, 60, 7, 190,
   'slow', 190, 20, 2, false, false, false,
   25, null, null, '{"animated":"/sprites/pokemon/58.gif","animated_shiny":"/sprites/pokemon/shiny/58.gif"}'),
  (59, 'arcanine', 59, true, 1,
   '{"ko":"윈디","en":"Arcanine","ja":"ウインディ","zh-Hans":"风速狗","zh-Hant":"風速狗","fr":"Arcanin","de":"Arkani","es":"Arcanine","it":"Arcanine"}',
   '{"ko":"전설포켓몬","en":"Legendary Pokémon","ja":"でんせつポケモン","zh-Hans":"传说宝可梦","zh-Hant":"傳說寶可夢","fr":"Pokémon Légendaire","de":"Legendär-Pokémon","es":"Pokémon Leyenda","it":"Pokémon Leggenda"}',
   '{"ko":"옛날부터 많은 사람의 마음을 사로잡은 아름다운 포켓몬이다. 마치 나는 것처럼 경쾌하게 달린다.","en":"Snaps at its foes with fangs cloaked in blazing flame. Despite its bulk, it deftly feints every which way, leading opponents on a deceptively merry chase as it all but dances around them.","ja":"昔から　多くの　人を虜にした　美しい　ポケモン。飛ぶように　軽やかに　走る。","zh-Hans":"从古时候起就是俘获了众多人心的美丽宝可梦。能像飞一样轻巧地奔跑。","zh-Hant":"從古時候起就是擄獲眾多人心的美麗寶可夢。能像飛一樣輕盈地奔跑。","fr":"Ce Pokémon est admiré depuis toujours pour sa beauté. Il court avec tellement de légèreté qu’on dirait qu’il vole.","de":"Dieses Pokémon verzaubert die Menschen seit Urzeiten mit seiner Schönheit. Obendrein ist es schnell und sehr wendig.","es":"Muchos han quedado cautivados por su belleza desde la antigüedad. Corre ágilmente como si tuviera alas.","it":"Da sempre ammirato per la sua bellezza, corre veloce come se avesse le ali."}',
   'fire', null, 90, 110, 80, 100, 80, 95, 19, 1550,
   'slow', 75, 20, 2, false, false, false,
   25, 58, '{"trigger":"use-item","item":{"id":"fire-stone","names":{"ko":"불꽃의돌","en":"Fire Stone","ja":"ほのおのいし","zh-Hans":"火之石","zh-Hant":"火之石","fr":"Pierre Feu","de":"Feuerstein","es":"Piedra Fuego","it":"Pietrafocaia"}}}', '{"animated":"/sprites/pokemon/59.gif","animated_shiny":"/sprites/pokemon/shiny/59.gif"}'),
  (60, 'poliwag', 60, true, 1,
   '{"ko":"발챙이","en":"Poliwag","ja":"ニョロモ","zh-Hans":"蚊香蝌蚪","zh-Hant":"蚊香蝌蚪","fr":"Ptitard","de":"Quapsel","es":"Poliwag","it":"Poliwag"}',
   '{"ko":"올챙이포켓몬","en":"Tadpole Pokémon","ja":"おたまポケモン","zh-Hans":"蝌蚪宝可梦","zh-Hant":"蝌蚪寶可夢","fr":"Pokémon Têtard","de":"Kaulquappen-Pokémon","es":"Pokémon Renacuajo","it":"Pokémon Girino"}',
   '{"ko":"유속이 빠른 강에서는 두꺼운 입술을 흡반처럼 사용해 바위에 달라붙는다.","en":"In rivers with fast-flowing water, this Pokémon will cling to a rock by using its thick lips, which act like a suction cup.","ja":"流れが　速い　川ではぶ厚い　唇を　吸盤のように岩に　くっつけて　しがみつく。","zh-Hans":"在水流湍急的河里，会把厚厚的嘴唇像吸盘那样紧紧吸在岩石上避免被冲走。","zh-Hant":"在水流湍急的河川裡，會把厚厚的嘴唇當作吸盤，吸附在岩石上避免被沖走。","fr":"Dans les rivières au courant puissant, il se sert de ses lèvres épaisses comme d’une ventouse pour s’accrocher aux rochers.","de":"In schnell fließenden Flüssen hält es sich mithilfe seiner dicken Lippen, die als Saugnapf fungieren, an Felsen fest.","es":"En ríos de aguas bravas, usa sus gruesos labios a modo de ventosa para adherirse a las rocas.","it":"Nei fiumi dalla corrente impetuosa, si attacca alle rocce utilizzando le spesse labbra come una ventosa."}',
   'water', null, 40, 50, 40, 40, 40, 90, 6, 124,
   'medium-slow', 255, 20, 4, false, false, false,
   26, null, null, '{"animated":"/sprites/pokemon/60.gif","animated_shiny":"/sprites/pokemon/shiny/60.gif"}'),
  (61, 'poliwhirl', 61, true, 1,
   '{"ko":"슈륙챙이","en":"Poliwhirl","ja":"ニョロゾ","zh-Hans":"蚊香君","zh-Hant":"蚊香君","fr":"Têtarte","de":"Quaputzi","es":"Poliwhirl","it":"Poliwhirl"}',
   '{"ko":"올챙이포켓몬","en":"Tadpole Pokémon","ja":"おたまポケモン","zh-Hans":"蝌蚪宝可梦","zh-Hant":"蝌蚪寶可夢","fr":"Pokémon Têtard","de":"Kaulquappen-Pokémon","es":"Pokémon Renacuajo","it":"Pokémon Girino"}',
   '{"ko":"미끈미끈한 점액 형태의 땀을 흘린다. 적에게 붙잡혀도 스르륵 빠져나와 도망친다.","en":"This Pokémon’s sweat is a slimy mucus. When captured, Poliwhirl can slither from its enemies’ grasp and escape.","ja":"ぬめぬめとした　粘液状の汗を　かく。　敵に　捕まってもぬるりと　すり抜け　逃げるのだ。","zh-Hans":"流出的汗是黏滑的粘液状。即使被敌人捉住，也能哧溜一下滑走逃脱。","zh-Hant":"流的汗是又黏又滑的黏液狀。即使被敵人捉住，也能滑溜溜地輕易逃脫。","fr":"Il sécrète une sorte de mucus huileux qui lui permet d’échapper aux ennemis qui tentent de l’attraper.","de":"Quaputzi schwitzt glitschigen Schleim, dank dem es leicht der Umklammerung eines Feindes entkommen kann.","es":"Secreta un sudor viscoso que le sirve para escurrirse y escapar del agarre de sus enemigos.","it":"Secerne un sudore viscido simile a muco, grazie al quale riesce a fuggire sgusciando via dalla presa dei nemici."}',
   'water', null, 65, 65, 65, 50, 50, 90, 10, 200,
   'medium-slow', 120, 20, 4, false, false, false,
   26, 60, '{"trigger":"level-up","min_level":25}', '{"animated":"/sprites/pokemon/61.gif","animated_shiny":"/sprites/pokemon/shiny/61.gif"}'),
  (62, 'poliwrath', 62, true, 1,
   '{"ko":"강챙이","en":"Poliwrath","ja":"ニョロボン","zh-Hans":"蚊香泳士","zh-Hant":"蚊香泳士","fr":"Tartard","de":"Quappo","es":"Poliwrath","it":"Poliwrath"}',
   '{"ko":"올챙이포켓몬","en":"Tadpole Pokémon","ja":"おたまポケモン","zh-Hans":"蝌蚪宝可梦","zh-Hant":"蝌蚪寶可夢","fr":"Pokémon Têtard","de":"Kaulquappen-Pokémon","es":"Pokémon Renacuajo","it":"Pokémon Girino"}',
   '{"ko":"헤엄뿐만 아니라 격투기도 특기다. 단련한 팔로 호쾌하게 펀치를 날린다.","en":"Poliwrath is skilled at both swimming and martial arts. It uses its well-trained arms to dish out powerful punches.","ja":"泳ぎ　だけでなく　格闘技も　得意。鍛えあげた　腕から豪快な　パンチを　繰りだす。","zh-Hans":"除了游泳还擅长格斗技。能用经过锻炼的手臂使出豪迈强力的拳击。","zh-Hant":"除了游泳之外，也擅長使用格鬥技。完美鍛鍊的手臂可以使出豪邁的拳擊。","fr":"Aussi habile à la nage qu’au combat, il peut donner de vigoureux coups de poing avec ses bras musclés.","de":"Es ist sowohl ein begnadeter Schwimmer als auch Kampfsportler. Mit seinen durchtrainierten Armen teilt es kräftige Schläge aus.","es":"No solo es un experto nadador, sino que también domina las artes marciales. Propina enérgicos puñetazos gracias a sus musculosos brazos.","it":"È abile sia nel nuoto che nella lotta corpo a corpo. Sferra pugni vigorosi grazie alle sue braccia allenate."}',
   'water', 'fighting', 90, 95, 95, 70, 90, 70, 13, 540,
   'medium-slow', 45, 20, 4, false, false, false,
   26, 61, '{"trigger":"use-item","item":{"id":"water-stone","names":{"ko":"물의돌","en":"Water Stone","ja":"みずのいし","zh-Hans":"水之石","zh-Hant":"水之石","fr":"Pierre Eau","de":"Wasserstein","es":"Piedra Agua","it":"Pietraidrica"}}}', '{"animated":"/sprites/pokemon/62.gif","animated_shiny":"/sprites/pokemon/shiny/62.gif"}'),
  (63, 'abra', 63, true, 1,
   '{"ko":"캐이시","en":"Abra","ja":"ケーシィ","zh-Hans":"凯西","zh-Hant":"凱西","fr":"Abra","de":"Abra","es":"Abra","it":"Abra"}',
   '{"ko":"초능력포켓몬","en":"Psi Pokémon","ja":"ねんりきポケモン","zh-Hans":"念力宝可梦","zh-Hant":"念力寶可夢","fr":"Pokémon Psy","de":"Psi-Pokémon","es":"Pokémon Psi","it":"Pokémon Psico"}',
   '{"ko":"잠이 든 상태에서 순간이동이 가능하다. 깊이 잠들수록 먼 곳으로 이동한다고 한다.","en":"Spends 18 hours of the day sleeping. Even while asleep, Abra can control its psychic powers—should danger approach, the Pokémon will simply teleport away.","ja":"眠ったまま　テレポート　できる。眠りが　深いほど　離れた　場所に移動する　という。","zh-Hans":"能够在睡梦中使出瞬间移动。据说它睡得越熟，就能移动到越遥远的地方。","zh-Hant":"就算在睡夢中也能使用瞬間移動。據說當牠睡得越熟，瞬間移動的距離就會越遠。","fr":"Il peut se téléporter en dormant. On dit que plus son sommeil est profond, plus il se téléporte loin.","de":"Es kann sich im Schlaf teleportieren. Je tiefer Abra schläft, desto weiter entfernt soll der Ort sein, an den es sich teleportiert.","es":"Puede teletransportarse mientras duerme. Se dice que, cuanto más profundo sea su sueño, mayor será la distancia a la que se desplace.","it":"È in grado di teletrasportarsi mentre dorme. Si dice che più profondo sia il suo sonno, più possa spostarsi lontano."}',
   'psychic', null, 25, 20, 15, 105, 55, 90, 9, 195,
   'medium-slow', 200, 20, 2, false, false, false,
   27, null, null, '{"animated":"/sprites/pokemon/63.gif","animated_shiny":"/sprites/pokemon/shiny/63.gif"}'),
  (64, 'kadabra', 64, true, 1,
   '{"ko":"윤겔라","en":"Kadabra","ja":"ユンゲラー","zh-Hans":"勇基拉","zh-Hant":"勇基拉","fr":"Kadabra","de":"Kadabra","es":"Kadabra","it":"Kadabra"}',
   '{"ko":"초능력포켓몬","en":"Psi Pokémon","ja":"ねんりきポケモン","zh-Hans":"念力宝可梦","zh-Hant":"念力寶可夢","fr":"Pokémon Psy","de":"Psi-Pokémon","es":"Pokémon Psi","it":"Pokémon Psico"}',
   '{"ko":"염동력의 위력은 절대적이다. 진화에 대비하여 이마에 있는 별에 사이코 파워를 비축하고 있다.","en":"There are rumors that a child with mystical powers became a Kadabra; however, this remains unverified. I suspect that the spoon Kadabra holds enhances its brain waves.","ja":"念力の　威力は　絶大。進化に　備えて　額の　星にサイコパワーを　蓄えている。","zh-Hans":"念力的威力大得惊人。会把精神力量储存在额头的星星里，以备进化之需。","zh-Hant":"念力的威力大得驚人。會把精神力量儲存在額頭的星星裡，以備進化所需。","fr":"Incroyablement doué en télékinésie, il concentre son énergie psychique dans l’étoile sur son front en prévision de son évolution.","de":"Kadabra verfügt über enorme psychokinetische Macht. Als Vorbereitung für seine Entwicklung speichert es im Stern auf der Stirn Psycho-Kräfte.","es":"La potencia de su telequinesis es inmensa. Acumula poder psíquico en la estrella de la frente como preparativo de cara a su evolución.","it":"La potenza della sua psicocinesi è immensa. Immagazzina i suoi poteri psichici nella stella sulla fronte, preparandosi all’evoluzione."}',
   'psychic', null, 40, 35, 30, 120, 70, 105, 13, 565,
   'medium-slow', 100, 20, 2, false, false, false,
   27, 63, '{"trigger":"level-up","min_level":16}', '{"animated":"/sprites/pokemon/64.gif","animated_shiny":"/sprites/pokemon/shiny/64.gif"}'),
  (65, 'alakazam', 65, true, 1,
   '{"ko":"후딘","en":"Alakazam","ja":"フーディン","zh-Hans":"胡地","zh-Hant":"胡地","fr":"Alakazam","de":"Simsala","es":"Alakazam","it":"Alakazam"}',
   '{"ko":"초능력포켓몬","en":"Psi Pokémon","ja":"ねんりきポケモン","zh-Hans":"念力宝可梦","zh-Hant":"念力寶可夢","fr":"Pokémon Psy","de":"Psi-Pokémon","es":"Pokémon Psi","it":"Pokémon Psico"}',
   '{"ko":"강력한 초능력을 구사한다. 양손에 든 숟가락은 그 힘으로 만들어낸 것이라고 한다.","en":"The longer Alakazam lives, the larger and heavier its head becomes. Our tests have shown that the strength of its psychic powers correlates positively to the weight of its head.","ja":"強力な　超能力を　操る。両手の　スプーンはその　力で　作りだしたという。","zh-Hans":"会操纵强大的超能力。据说它双手握着的汤勺就是用那力量制造出来的。","zh-Hant":"能操控強大的超能力。雙手中的湯匙據說就是用牠的力量創造出來的。","fr":"Il dispose d’immenses pouvoirs psychiques. On raconte qu’il s’en est servi afin de créer les cuillères qu’il tient dans chaque main.","de":"Simsala verfügt über extrem starke Psycho-Kräfte. Mit ihnen soll es die Löffel erschaffen haben, die es in seinen Händen hält.","es":"Posee unos poderes psíquicos extraordinarios con los que, según se dice, creó las cucharas que lleva en las manos.","it":"Padroneggia potenti poteri psichici, con i quali si dice abbia creato i cucchiai che tiene in mano."}',
   'psychic', null, 55, 50, 45, 135, 95, 120, 15, 480,
   'medium-slow', 50, 20, 2, false, false, false,
   27, 64, '{"trigger":"trade"}', '{"animated":"/sprites/pokemon/65.gif","animated_shiny":"/sprites/pokemon/shiny/65.gif"}'),
  (66, 'machop', 66, true, 1,
   '{"ko":"알통몬","en":"Machop","ja":"ワンリキー","zh-Hans":"腕力","zh-Hant":"腕力","fr":"Machoc","de":"Machollo","es":"Machop","it":"Machop"}',
   '{"ko":"괴력포켓몬","en":"Superpower Pokémon","ja":"かいりきポケモン","zh-Hans":"怪力宝可梦","zh-Hant":"怪力寶可夢","fr":"Pokémon Colosse","de":"Kraftprotz-Pokémon","es":"Pokémon Superpoder","it":"Pokémon Megaforza"}',
   '{"ko":"언제나 파워풀하다. 체력이 남아돌기 때문에 심심풀이로 바위를 들어 올리며 더 강해진다.","en":"Though as small as a child, it has strength enough to easily throw a well-built adult. Striving to become ever stronger, Machop trains by carrying a Graveler on its shoulders.","ja":"いつも　パワフル。　体力が有り余っているので　暇つぶしに岩を持ち上げ　さらに　強くなる。","zh-Hans":"时时刻刻都充满力量。由于体力过剩而去举起岩石消磨时间，也因此变得更强。","zh-Hant":"時時刻刻都充滿力量。由於體力過剩而去舉岩石消磨時間，也因此變得更強。","fr":"Il essaie de dépenser son énergie débordante en soulevant des rochers, ce qui le rend encore plus fort.","de":"Da es vor Kraft strotzt, hebt es zum Zeitvertreib Felsen. Dadurch gewinnt es an zusätzlicher Stärke.","es":"Siempre rebosante de energía, pasa el tiempo levantando piedras para hacerse aún más fuerte.","it":"Sempre traboccante di energia, passa il tempo a sollevare massi. Così diventa ancora più forte."}',
   'fighting', null, 70, 80, 50, 35, 35, 35, 8, 195,
   'medium-slow', 180, 20, 2, false, false, false,
   28, null, null, '{"animated":"/sprites/pokemon/66.gif","animated_shiny":"/sprites/pokemon/shiny/66.gif"}'),
  (67, 'machoke', 67, true, 1,
   '{"ko":"근육몬","en":"Machoke","ja":"ゴーリキー","zh-Hans":"豪力","zh-Hant":"豪力","fr":"Machopeur","de":"Maschock","es":"Machoke","it":"Machoke"}',
   '{"ko":"괴력포켓몬","en":"Superpower Pokémon","ja":"かいりきポケモン","zh-Hans":"怪力宝可梦","zh-Hant":"怪力寶可夢","fr":"Pokémon Colosse","de":"Kraftprotz-Pokémon","es":"Pokémon Superpoder","it":"Pokémon Megaforza"}',
   '{"ko":"지치지 않는 강인한 육체를 가졌다. 무거운 물건을 옮기는 등의 일을 돕는다.","en":"A sturdy creature boasting a robust physique and boundless stamina. Loves training above all else and voluntarily assists with tasks such as construction and clearing land.","ja":"疲れることのない　強靭な肉体を　もつ。　重い　荷物の運搬などの　仕事を　手伝う。","zh-Hans":"有着不会疲劳的强韧肉体。会去帮助人类完成例如搬运沉重行李之类的工作。","zh-Hant":"有著不會疲勞的強韌肉體。會去幫助人類完成例如搬運沉重行李之類的工作。","fr":"Son corps robuste ne se fatigue jamais. Il n’hésite pas à aider les gens lorsqu’il s’agit de soulever des objets très lourds.","de":"Sein durchtrainierter Körper wird nie müde. Es hilft den Menschen, indem es schwere Sachen trägt.","es":"Tiene una complexión tan fuerte que nunca se cansa. Suele ayudar a la gente a cargar objetos pesados.","it":"Ha un fisico vigoroso e instancabile. Aiuta le persone a trasportare carichi e a svolgere altri lavori pesanti."}',
   'fighting', null, 80, 100, 70, 50, 60, 45, 15, 705,
   'medium-slow', 90, 20, 2, false, false, false,
